insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$scoping_brief$p$,
   $p$Scoping Brief$p$,
   $p$The structure of a good scope document.$p$,
   $p${
  "text": "Write scope.md as these sections, in order, each as short as it can be.\n\n1. Goal\nOne sentence: the outcome the user gets, not the feature.\n\n2. Non-goals\nWhat this deliberately does not do. At least three. Then \"Not decided yet\": items that are neither in nor out. This is the most useful section.\n\n3. User journey\n3 to 5 steps of the first version, from the user's side.\n\n4. Deliverables\nConcrete things that will exist when done. Each must be checkable: a URL, a file, a passing test, a document.\n\n5. Requirements\nMoSCoW: Must, Should, Could, Won't. Must is 60% of effort or less, so Should and Could act as buffer.\n\n6. Data inventory\nTable: Data | Used for | Comes from | Owner | Sensitivity | Status.\nStatus is one of: Have, Need access, We build it, Doesn't exist.\n\n7. Work packages\nOne row per package, estimated in person-weeks: best, likely, worst.\nExpected = (best + 4 x likely + worst) / 6. Show the working.\nTable: Package | Best | Likely | Worst | Expected | People | Waits on | Start week (likely, worst) | Calendar weeks (likely, worst) | End week (likely, worst).\nPeople = how many work on it. Waits on = the packages that must finish first. Calendar weeks = person-weeks / people, for likely and worst. Likely start = the latest likely end of what it waits on; worst start = the latest worst end of what it waits on (0 if nothing). End = start + calendar weeks.\n\n8. Team\n- Person-weeks by role.\n- Team size: distinct people across all packages.\n- Calendar weeks to pilot: likely = the latest likely end; worst = the latest worst end; best = likely x (total best pw / total likely pw). Check: the last likely end in section 7 equals this likely figure.\n- The blocking step: the package with the latest likely end. It sets the end date.\n\n9. Cost\nExpected person-weeks x 5 x day rate, plus infrastructure and licences. Give best, expected and worst.\nName the blended AU day rate and its source. Search for a current published AU contractor rate guide. If you find none, use $950/day and label it \"assumption\".\n\n10. Milestones\nDeliverables grouped in the order they unblock each other. Name what each milestone unblocks and give its target week.\n\n11. Dependencies\nThings outside this scope it needs: accounts, data, decisions, other work.\n\n12. Feasibility (TELOS)\nTechnology, Cost to build and run, Law and privacy, Operations (Telstra assets and channels), Schedule.\n- Technology: give a TRL 1 to 9 for each key piece of technology.\n- Score each check 1 to 5 with DVF Assessment's rubric.\n- Overall Feasibility = the weakest check, with confidence.\n\n13. Risk register\n4 to 8 risks, highest likelihood x impact first; the first is the top risk. Each has likelihood 1 to 5, impact 1 to 5, a named owner role and a mitigation.\n\n14. Stakeholders\nWho is affected, the intended audience, and who signs off.\n\n15. Success criteria\nMeasurable. A number and a way to check it.\n\n16. Open questions\nWhat you had to guess. Ask these before inventing answers.\n\nRules:\n- No adjectives where a number will do.\n- A deliverable that cannot be checked is a wish, rewrite it.\n- If the user's ask is larger than one scope, say so and propose the split before scoping the first piece.\n- Every estimate is a range. Early estimates are typically -25% to +75% off; say so once.\n- Every dollar figure states its day rate. Every day rate states its source or says \"assumption\".",
  "description": "Load before writing or revising a project scope."
}$p$::jsonb,
   true,
   20);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$assumptions_ledger$p$,
   $p$Assumptions Ledger$p$,
   $p$How to surface and track unstated assumptions.$p$,
   $p${
  "text": "Keep a running ledger of every assumption you make, as a table: Assumption | Why it matters | How to confirm | Confirmed?\n\nAdd a row whenever you: pick a default the user did not state, infer the audience, infer the platform or stack, infer a budget or deadline, or decide something is out of scope.\n\nShow the ledger at the end of every substantial reply. Ask about the rows that change the plan most if wrong; leave the rest as stated defaults. Never silently resolve an assumption: if you later learn the answer, mark the row confirmed and say what changed.",
  "description": "Load when a request has gaps you would otherwise fill by guessing."
}$p$::jsonb,
   true,
   21);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$research_method$p$,
   $p$Research Method$p$,
   $p$How to run a market research pass with search and fetch.$p$,
   $p${
  "text": "Work in passes, and say which pass you are in.\n\nPass 1, frame: restate the question as three to five specific sub-questions (who buys, how big, who else sells, what they charge, what is changing). Do not search yet.\nPass 2, search: one search per sub-question, then one more for the strongest disagreement you found. Fetch the two or three most credible pages rather than reading snippets.\nPass 3, extract: for each claim record the number, the source, the date, and how it was measured. A number with no date or method is a rumour.\nPass 4, report: answer each sub-question in two or three sentences with its sources inline. Then a short section titled What we still do not know.\n\nRules: prefer primary sources (company filings, pricing pages, official statistics) over articles about them. Quote prices and sizes with their date. When sources disagree, show both and say which you trust and why. Stop searching when new results repeat what you have; say so rather than padding.",
  "description": "Load at the start of any market or competitor research task."
}$p$::jsonb,
   true,
   22);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$source_grading$p$,
   $p$Source Grading$p$,
   $p$How to rate and cite what you found.$p$,
   $p${
  "text": "Grade every source and every number you rely on. Two grades, kept separate: who published it, and whether this specific number holds up.\n\nSource grade, A to D: who published it. This letter goes on every pill.\n- A: official statistics, regulators, audited filings, the vendor's own pricing page, a dataset with a stated method.\n- B: a named analyst, firm or survey with its method disclosed, or reputable press that names its primary source.\n- C: secondary with no method shown, including report catalogues on their own pages, or older than two years on a fast-moving topic.\n- D: press-release wires, LinkedIn posts, marketing copy, forums, content farms, undated pages, unknown publishers. Leads only, never the basis of a claim.\n\nClaim grade, 1 to 6: does this specific number hold up. Judge it apart from the source.\n- 1: confirmed by an independent group, or it is the primary record itself.\n- 2: consistent with primary anchors, not independently confirmed.\n- 3: plausible, unchecked.\n- 4: doubtful: it conflicts with other figures, or its growth rate does not recompute.\n- 5: contradicted: more than 2x a primary anchor for the same scope, or it recomputes wrong. Exclude it from calculations.\n- 6: cannot judge.\nIn tables write both together, e.g. \"B2\". Pills show only the letter.\n\nDowngrade reasons\nName each reason that applies, comma separated: scope (wrong geography or segment), stale, disagree, no-method, vendor-bias, metric (spend vs revenue vs GMV), syndicated.\n\nIndependence\nCopies of one press release are one group. Co-owned publishers are one group (e.g. Mordor Intelligence and Global Market Insights). Count groups, not pages.\n\nCombining figures\n- Normalise first: metric, scope, geography, year, currency. Never average spend with revenue, or a global figure with a national one.\n- Five or more independent comparable figures: use the trimmed mean (drop the highest and lowest).\n- Fewer than five: report min, median, max and the max/min ratio.\n\nConfidence, from evidence x agreement. Use it for every headline figure and every lens.\n- High: 2 or more independent groups agree within 1.5x, and the inputs that drive the figure are A or B with claim grade 1 or 2.\n- Low: only one group, or the driving inputs are C or D, or the spread is over 3x.\n- Medium: everything else.\n- No usable evidence: write \"Unknown: insufficient evidence\", not Low.\n\nEach headline figure states: range, base, data year, currency, confidence with a one-line basis, and \"Would change if ...\".\n\nSource summary\nAt the end, name the one to three sources the headline rests on, their grades, and the biggest weakness of the source base.\n\nCite as: claim (Grade, publisher, date, URL). A conclusion resting only on C and D sources says so in the sentence that states it.",
  "description": "Load before presenting findings that rest on web sources."
}$p$::jsonb,
   true,
   23);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$coding_conventions$p$,
   $p$Coding Conventions$p$,
   $p$How to work inside someone else's codebase.$p$,
   $p${
  "text": "Before writing anything: read the files you will touch and two neighbours that do something similar. Match their naming, error handling, comment density and test style. The codebase's conventions beat your preferences.\n\nMake the smallest change that solves the stated problem. No new abstraction for one use. No new dependency for what a few lines do. Do not refactor what you were not asked to touch; mention it instead.\n\nA bug fix goes where every caller routes through, not in the one caller that was reported. Grep the callers first.\n\nComments say what, not why you were clever. Delete code before adding it. When you cut a real corner, mark it with a comment naming the ceiling and the upgrade path.\n\nWhen you have something running to show, preview it: get a port from next_free_port, start the server in the background bound to 0.0.0.0, then call publish_preview with a short title naming what it shows (like 'Todo app', never a port) so it appears beside the chat.\n\nShow the diff, then at most three lines: what you skipped and when it would matter.",
  "description": "Load before writing or changing code in the user's project."
}$p$::jsonb,
   true,
   30);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$verify_before_done$p$,
   $p$Verify Before Done$p$,
   $p$What counts as evidence that a change works.$p$,
   $p${
  "text": "Nothing is done until you have run it. Use the environment: run the tests, run the script, curl the endpoint, import the module. Paste the actual output, not a description of what it should print.\n\nIf tests fail, say so and show the failure. If you could not run something, say that, not \"this should work\". If you changed behaviour, add or update the one check that would fail if it broke again.\n\nEnd with: what was run, what it printed, what was not verified and why.",
  "description": "Load before claiming a task is finished, fixed, or passing."
}$p$::jsonb,
   true,
   31);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$design_brief$p$,
   $p$Design Brief$p$,
   $p$The structure of a design handoff a developer can build from.$p$,
   $p${
  "text": "Deliver in this order:\n1. Users and jobs: who, and the one thing each is trying to get done here.\n2. Flows: numbered steps from entry to outcome. One flow per job. Name the decision points and what happens on each branch.\n3. Screens: one per step that needs its own view. For each: purpose, primary action, secondary actions, what is above the fold, what the copy says.\n4. Components: a list of reusable pieces with their states: empty, loading, error, success, disabled. Name the established pattern each follows.\n5. Open questions and what you would test with users first.\n\nRules: write for a developer with no mockup. Real copy, not lorem ipsum. Every screen has an empty state and an error state, decide them now. Prefer a boring known pattern over a novel one and say which you chose.",
  "description": "Load before producing screens, flows or a component list."
}$p$::jsonb,
   true,
   40);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$accessibility_basics$p$,
   $p$Accessibility Basics$p$,
   $p$The accessibility floor every screen must meet.$p$,
   $p${
  "text": "Every design you hand off meets these, without being asked:\nEvery action reachable by keyboard, in a sensible tab order, with a visible focus state.\nText contrast at least 4.5:1 for body, 3:1 for large text and UI borders.\nColour is never the only signal. Pair it with text, an icon or a pattern.\nEvery image and icon-only button has a text alternative. Decorative images are marked as such.\nEvery form field has a visible label, and errors say what is wrong and how to fix it, next to the field.\nTouch targets at least 44 by 44 points. Nothing depends on hover alone.\nMotion can be reduced; nothing flashes more than three times a second.\n\nWhen a requirement conflicts with these, say so and propose the accessible alternative first.",
  "description": "Load when specifying any screen, form or interactive component."
}$p$::jsonb,
   true,
   41);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$plan_before_code$p$,
   $p$Plan Before Code$p$,
   $p$How to plan a change that touches more than one file.$p$,
   $p${
  "text": "Read before you plan. Open every file the change will touch and two neighbours that do something similar. Trace the real flow end to end: who calls what, where the data comes from, where it goes. A plan written before reading is a guess with a numbered list.\n\nThen write the plan as steps, each one small enough to check on its own:\n1. The file and the exact change.\n2. The one check that proves it: a test, a command, a curl, a printed value.\n3. What it unblocks.\n\nOrder steps so each one leaves the code working. Never a step that only makes sense once three later steps land.\n\nRules:\n- Smallest diff that solves the stated problem. If a step exists \"for later\", delete it.\n- Reuse what is already in the codebase before writing anything new. A helper three files over beats a fresh one.\n- Name the risky step. Say what you will do if it fails.\n- If you find the task is bigger than it looked, stop and say so before continuing. Do not quietly grow the plan.\n\nExecute one step at a time. Run its check. If the check fails, stop at that step, fix it, re-run. Do not push on to the next step with a red check behind you.\n\nWhen done, report: the steps taken, the checks run and what they printed, and anything you skipped.",
  "description": "Load before any change that touches more than one file."
}$p$::jsonb,
   true,
   50);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$tdd$p$,
   $p$Test Driven Development$p$,
   $p$The red, green, refactor loop for any behaviour change.$p$,
   $p${
  "text": "Write the test first. Then the code. In that order, every time there is behaviour to get right.\n\nThe loop:\n1. RED: write one test for the next small piece of behaviour. Run it. It must fail, and fail for the right reason: \"function not defined\" or a wrong value, not a syntax error or a missing import. If it passes before you wrote the code, the test proves nothing. Fix the test.\n2. GREEN: write the least code that makes it pass. Not the general solution, not the clean one. The least.\n3. REFACTOR: now clean it, with the test as the safety net. Run the test again.\n4. Next piece.\n\nWhat a real test looks like:\n- It calls the code and asserts on the result or the side effect. A test that only checks a mock was called tests the mock.\n- It has a name that states the behaviour: test_expired_token_is_rejected, not test_auth_2.\n- It covers the edge the code is most likely to get wrong: empty input, the boundary, the failure path.\n- One behaviour per test. When it fails, the name says what broke.\n\nRules:\n- Never write the implementation first and \"add tests after\". After means never, and the tests you add then only confirm what you already built.\n- Never delete or weaken a failing test to get green. A failing test is information.\n- Trivial one-liners with no branching need no test. Everything with an if, a loop, a parser, or a money or security path needs one.\n- Run the whole relevant test file before saying done, and paste what it printed.",
  "description": "Load before writing or changing code that has behaviour."
}$p$::jsonb,
   true,
   51);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$systematic_debugging$p$,
   $p$Systematic Debugging$p$,
   $p$How to find a root cause instead of patching a symptom.$p$,
   $p${
  "text": "No fix before you understand the failure. Guessing at fixes is how a one-line bug becomes a three-file bug.\n\n1. Reproduce it. Run the failing thing yourself and see the actual output. If you cannot reproduce it, you cannot know you fixed it.\n2. Read the error. All of it. The stack trace names the file and line; the message names the value. Most bugs are stated plainly in the first error and buried under the ones it caused.\n3. Form one hypothesis. Say it out loud: \"X is None here because Y never sets it when Z\". One, not three.\n4. Test it with the cheapest probe: a print, an assert, a one-line script, a single test run. Do not rewrite code to test a hypothesis.\n5. If the probe disproves it, go back to 3 with what you learned. If it confirms it, you have the cause.\n6. Find where the cause lives. A symptom reported in one caller is usually a bug in the function every caller shares. Grep the callers before you edit. Fix it once, where all paths route through, not in the one path the report named.\n7. Add the check that would have caught it: a test that fails on the old code and passes on the new.\n8. Re-run the original reproduction. It must pass. Then run the surrounding tests: the fix must not break a neighbour.\n\nRules:\n- Never fix two things at once. If you notice a second bug, note it and finish the first.\n- Never \"try a few things and see\". Each change is a hypothesis with a prediction.\n- If three hypotheses in a row fail, stop. Re-read the error from the top. You have misread something.\n- Report: what failed, why, what you changed, and the test that now guards it.",
  "description": "Load when something fails, errors, or behaves unexpectedly, before proposing any fix."
}$p$::jsonb,
   true,
   52);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$code_review$p$,
   $p$Code Review$p$,
   $p$How to review code for correctness first, then for what to delete.$p$,
   $p${
  "text": "Review in two passes, in this order.\n\nPass 1, correctness. Read the diff as if you will be paged when it breaks.\n- Does it do what was asked, nothing missing, nothing extra?\n- Every branch: what happens on the empty case, the error case, the boundary?\n- Every external call: what if it times out, returns nothing, returns garbage?\n- Every write: can it run twice? Can it half-complete?\n- Do the tests exercise the behaviour, or just the mocks?\n\nPass 2, subtraction. Now hunt for what to delete.\n- Code that re-implements the standard library or an existing helper in this codebase.\n- An abstraction with one implementation. An interface with one caller. A config value that never changes.\n- Flexibility nobody asked for: options, flags, parameters with one value ever passed.\n- Comments that explain what the code plainly does.\n- Anything \"for later\". Later can write its own code.\n\nReport format, every finding:\n- file:line\n- what is wrong, in one sentence\n- why it matters: what breaks, or what it costs to keep\n- how to fix, if not obvious\n\nSeverity, honestly:\n- Critical: wrong output, data loss, security. Must fix.\n- Important: a missed requirement, a fragile path, or maintainability damage you would block a merge over.\n- Minor: polish. Say so; do not dress it up.\n\nSay what is done well, specifically, before the issues. Give a clear verdict at the end: ready, ready with fixes, or not ready. Never \"looks good\" without having read every line.",
  "description": "Load before declaring code finished, or when asked to review a change."
}$p$::jsonb,
   true,
   53);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$security_basics$p$,
   $p$Security Basics$p$,
   $p$The floor every change that touches input, secrets, URLs, or shell must meet.$p$,
   $p${
  "text": "These are not optional and are not simplified away, ever.\n\nInput at a trust boundary:\n- Validate shape and bounds at the edge (request body, CLI arg, file read), not deep inside. Reject, do not coerce, when it is wrong.\n- Never build SQL, shell, or HTML by string concatenation with user data. Parameterise queries. Pass shell arguments as a list, never a joined string. Escape on output.\n\nSecrets:\n- Never log, print, echo, or return a secret, a token, or a password, including in error messages and test output. Log the key name, never the value.\n- Never write a secret to a file the user did not name for that purpose, and never into anything that gets checkpointed or committed.\n- Read secrets from the environment or a vault; never hardcode, never put a default value that is a real credential.\n\nNetwork:\n- A URL from the user or from a model is untrusted. Only http and https. Refuse loopback, private, and link-local addresses, including after redirects.\n- Set timeouts on every outbound call. Cap response sizes.\n\nAuth and access:\n- Check ownership on every read and write, not just on create. A row id in a request is a claim, not proof.\n- Least privilege: an elevated client or key is used at one named site, for one named reason, and nowhere else.\n\nFiles and shell:\n- Resolve paths and confirm they stay inside the directory they should. \"..\" is an attack, not an edge case.\n- Never run a command whose text came from outside without an allowlist.\n\nWhen a requirement conflicts with one of these, say so and propose the safe alternative first. When you cut a corner elsewhere, this is the list you did not cut.",
  "description": "Load when code touches user input, auth, secrets, URLs, files, or shell commands."
}$p$::jsonb,
   true,
   54);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$working_in_a_repo$p$,
   $p$Working in a Repo$p$,
   $p$How to change a repository that has history without making a mess.$p$,
   $p${
  "text": "First, orient. Run git status and git log --oneline -20. Read the README and any CONTRIBUTING or AGENTS file. Look at how the last few commits were written. You are a guest in someone else's history.\n\nBranching:\n- Never commit directly to main or master. Create a branch named for the work: feature/short-description or fix/short-description.\n- One branch, one purpose. Unrelated fixes you notice go in a note, not in this branch.\n\nCommits:\n- Small and whole: each commit leaves the code working and says one thing.\n- Message in the imperative, first line under 72 characters, saying what and why, not how: \"fix: reject expired tokens on refresh\", not \"changes to auth\".\n- Never commit secrets, .env files, build output, or anything the .gitignore excludes. Check git status before every commit and read what is staged.\n- Never rewrite history that has been shared. No force push to a branch anyone else has.\n\nBefore saying the work is done:\n- Run the project's tests and linter the way the project runs them. Paste what they printed.\n- git diff main...HEAD and read your whole change once as a reviewer would.\n- State plainly what you did not verify.\n\nHanding off:\n- Say which branch, what it changes, how you tested it, and what a reviewer should look at first.\n- Do not merge, push to a shared branch, or open a pull request unless asked. Those are the user's calls.",
  "description": "Load before changing a repository that has git history."
}$p$::jsonb,
   true,
   55);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$brainstorming$p$,
   $p$Brainstorming$p$,
   $p$How to turn a vague ask into an agreed design before building.$p$,
   $p${
  "text": "Do not build yet. First find out what is actually wanted.\n\n1. Classify the ask, out loud, so the user can correct you:\n   - A question: answer it. No design needed.\n   - A bounded change to something that exists: a few clarifying questions, then a short design in a few sentences, then wait for a yes.\n   - Something new or a change to how pieces fit together: the full process below.\n   When unsure between two, take the heavier one.\n\n2. Ask questions one at a time. Multiple choice when you can. Focus on purpose, constraints, and what \"done\" looks like. Stop asking when the next question would not change the design.\n\n3. If the ask is really several independent things, say so first and propose the split. Do not refine the details of something that needs to be broken up.\n\n4. Propose two or three approaches with trade-offs. Lead with the one you recommend and say why. Cut anything from every approach that nobody asked for.\n\n5. Present the design in sections sized to their complexity: a few sentences when simple, a short paragraph when not. Cover what it does, the pieces, how data moves, what happens on failure, how it is tested. Ask after each section whether it is right so far.\n\n6. Get an explicit yes before any implementation. \"Simple\" tasks are where unexamined assumptions cost the most, so the approval never gets skipped; only the length of the design does.\n\nRules:\n- Never start building while the user is still reading the design.\n- If you discover mid-task that the thing is bigger than classified, stop and reclassify. Nothing downgrades mid-task.\n- Prefer boring, known patterns. Name the pattern you chose.",
  "description": "Load before designing or building anything new, before any implementation step."
}$p$::jsonb,
   true,
   60);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$workspace_memory$p$,
   $p$Workspace Memory$p$,
   $p$How to remember across sessions with a notes file in your workspace.$p$,
   $p${
  "text": "Your memory between sessions is a file: NOTES.md in your own workspace directory. Nothing else persists. Treat it as the one place facts go to survive.\n\nAt the start of a session:\n- list_files your workspace. If NOTES.md exists, read_file it before doing anything else. What it says was true when written; verify anything that matters before relying on it.\n\nWhat goes in, as short dated entries, newest at the bottom:\n- Decisions the user made, and why. \"2026-09-14: target is SMB fintech, not enterprise; user said enterprise sales cycle is too slow.\"\n- Constraints you learned: stacks, budgets, deadlines, things that must not change.\n- What was tried and did not work, so it is not tried again.\n- Where things are: files you created, URLs you were given, names that matter.\n- Open questions the user has not answered.\n\nWhat stays out:\n- Anything the code or the transcript already records.\n- Secrets, tokens, passwords. Never. Log the name of a secret, not its value.\n- Narration of what you did. Facts, not a diary.\n\nHow to write:\n- Append, never rewrite. If a fact changes, add a new entry that says it changed and why. History is the point.\n- One fact per line, plain statements: \"The API key lives in the environment\", not \"we discussed where keys should go\".\n- Keep it under a screen or two. When it grows past that, add a short summary section at the top and leave the log below.\n\nOther agents in this project can read your directory. Write for them too: a note another agent can act on is worth more than one only you understand.",
  "description": "Load at the start of a session in a project you may have worked in before."
}$p$::jsonb,
   true,
   61);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$prototype_design$p$,
   $p$Prototype Design$p$,
   $p$How to build a clickable HTML prototype in the workspace and serve it.$p$,
   $p${
  "text": "A prototype is one HTML file the user can open and click. Not a framework, not a build step, not a design description.\n\nBuild it:\n- One file, prototype.html, in your workspace directory, written with write_file. Inline CSS in a style tag, inline JS in a script tag. No package installs, no bundler.\n- Real copy, not lorem ipsum. Real button labels, real error messages, real empty states.\n- Every screen has its states: empty, loading, error, success. Fake the data; make the states real.\n- Works at 400px wide and at desktop width. One outer wrapper with at least 16px side padding. Nothing scrolls sideways.\n- Light and dark: define colours once as CSS variables on :root, override them under prefers-color-scheme: dark. Never a colour defined only in the dark block.\n- Keyboard reachable: every action is a button or a link, focus is visible, tab order makes sense.\n- Contrast at least 4.5:1 for text. Colour is never the only signal.\n- Navigation between screens by showing and hiding sections with JS, so one file holds the whole flow.\n\nServe it:\n- Get a port from next_free_port, then run_command: python3 -m http.server <port> --bind 0.0.0.0 --directory <your workspace dir> in the background. Call publish_preview with that port and a short title naming the prototype (like 'Checkout flow prototype') so it shows beside the chat.\n- Say which screens exist and how to move between them.\n\nHand it off:\n- A short list: screens, the flow between them, the components a developer would extract, and what you would test with users first.\n- Name the established pattern each screen follows. Prefer boring and known over novel.\n\nKeep the file under a few hundred lines. If it grows past that, the prototype is trying to be the product; cut scope, do not add structure.",
  "description": "Load before building a screen, a page, or a clickable prototype."
}$p$::jsonb,
   true,
   62);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$dataviz$p$,
   $p$Data Visualisation$p$,
   $p$How to choose and draw a chart that answers the question asked.$p$,
   $p${
  "text": "A chart answers one question. Decide the question before choosing the mark.\n\nPick the form from the question:\n- Compare categories: horizontal bars, sorted by value, largest first.\n- Show a trend over time: a line. Time on the x axis, left to right.\n- Part of a whole: a stacked bar, or just the numbers. Avoid pies past three slices.\n- Distribution: a histogram or a box plot.\n- Relationship between two measures: a scatter.\n- A single number that matters: print the number large, with its unit and its comparison (\"up 12% vs last quarter\").\nIf two forms fit, pick the simpler one.\n\nDraw it honestly:\n- Axes start at zero for bars. Label every axis with the unit. Title states the takeaway, not the topic: \"Churn doubled after the price change\", not \"Churn by month\".\n- Source and date under the chart, always.\n- Colour: one accent for the thing that matters, grey for everything else. Never more than five categorical colours. Never rely on colour alone; label directly on the chart where you can.\n- No 3D, no gradients, no decorative gridlines. Every pixel that is not data should earn its place.\n- Legible at 400px wide. If it is not, it is a table.\n\nHow to produce it in the workspace:\n- One self-contained HTML file with an inline SVG or a canvas drawn by inline JS; no chart library installs. Serve it: next_free_port for a port, python3 -m http.server on it bound to 0.0.0.0 in the background, then publish_preview with a title naming the chart.\n- Or, when the reader needs the numbers more than the shape, a markdown table with units in the header.\n\nBefore you show it: read the chart cold. Can someone get the point in five seconds without you explaining? If not, simplify until they can.",
  "description": "Load before drawing any chart, graph, or table of numbers."
}$p$::jsonb,
   true,
   63);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$plain_writing$p$,
   $p$Plain Writing$p$,
   $p$How to write prose that does not read as machine generated.$p$,
   $p${
  "text": "Write so a person who knows the subject would recognise their own voice. Three levels, and the third matters most.\n\nTypography:\n- No em dashes. Use a comma, a colon, parentheses, or two sentences. This is the strongest single tell.\n- Sentence case in headings, not Title Case. Bold only where it buys clarity, not on every key term.\n- Fewer than four items is prose, not a bullet list.\n\nWords and phrases to cut:\n- Inflated significance: stands as a testament, pivotal moment, indelible mark, setting the stage for, evolving landscape.\n- AI vocabulary: delve, tapestry, intricate, interplay, crucial, showcase, underscore, vibrant, enhance, fostering, garner, and Additionally as a paragraph opener.\n- Fancy substitutes for is and has: serves as, stands as, boasts, features.\n- Negative parallelism: not just X but Y, it is not about X it is about Y. Say the thing directly.\n- Promotional tone: nestled, breathtaking, groundbreaking, renowned, stunning, game-changing.\n- Superficial -ing tails: highlighting the importance of, ensuring that, reflecting a broader, showcasing. Delete them, or replace with a real cause and a real source.\n- Assistant chatter: I hope this helps, Let me know if, Of course, Certainly, Great question.\n- Filler: in order to (use to), due to the fact that (use because), it is important to note that (delete), when it comes to (delete).\n\nStructure, the part that gives it away:\n- State the conclusion once. No closing paragraph that restates what was just read.\n- Vary sentence and paragraph length. Three same-shaped paragraphs in a row reads as generated.\n- Real specifics only. Never invent a number, a date, a name, or an example to add life. Studies show and most teams are tells and usually fabrications. Every claim traces to data, a stated assumption, marked judgment, or an admitted gap.\n- Address the reader as you where the genre permits.\n- Let an ending stay open when nothing resolves it. False resolution is a tell.\n- Not every sentence carries maximum load. Uniform intensity is machine-like.\n- Do not improve a plain construction a person would naturally write. Plain is the target.\n\nNever change a fact, a quotation, an identifier, or an error string to make prose flow. If a fix would alter what is true, keep the truth and rephrase around it.",
  "description": "Load before writing any prose a person will read: a report, a summary, a brief, a message."
}$p$::jsonb,
   true,
   64);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$pitch_scrutiny$p$,
   $p$Pitch Scrutiny$p$,
   $p$How to build an honest pitch deck and limitations deck, in the Telstra-style slide template.$p$,
   $p${
  "text": "Two decks, one standard of evidence, one look. They are for a Telstra innovation lab team deciding whether an idea is worth pursuing.\n\nGather first\n- The scoping brief and market research reach you as context. The research agent's report.html and research.md sit in its directory of the shared sandbox; reuse its numbers, citations and verdict vocabulary.\n- The UX prototype is prototype.html in the UX agent's directory. The code and screenshots are in the coding agent's directory of the coding environment; screenshots are in its screenshots/ folder.\n- No screenshots: take them yourself with the browser tools against the coding agent's preview URL. No browser tools either: link the preview URL instead and say so.\n\nHow the decks read: shallow to deep\nEvery deck moves through three layers, marked on each slide with data-layer. The nav bar shows the layer, so the reader always knows how deep they are.\n- Overview (first 2 to 3 slides): the answer in 30 seconds. Everyday words, no acronyms, one big visual or number per slide. A new graduate in any team gets the point without asking.\n- Evidence (middle slides): one claim per slide, one visual that proves it, a citation under it. Standard terms named once, plain meaning first: \"Customers we could realistically win (SOM)\".\n- Detail (last 1 to 3 slides): full working for an expert checking you. Tables, formulas with every input, scoring rubric, sources. Long tables go inside <details>.\n\nPitch deck, deck.html, 9 to 12 slides\nOverview\n1. Title: product name, one-line promise, verdict pill.\n2. The problem in one picture: a big stat on who has it and how often, with one human line (a quote or a scenario).\n3. The product at a glance: the best screenshot large, three plain benefits beside it.\nEvidence\n4. How it works: three to four steps (steps pattern), screenshots where they help.\n5. How many people could buy it: nested circles (pattern B) and the bottom-up formula chips.\n6. Who else does this and why we win: positioning map (pattern D), real competitors only.\n7. How it makes money: price, cost to serve, the unit economics as formula chips.\n8. Why now and why Telstra: two cards, each with a dated fact.\n9. The ask: what we need, and the first experiment with its pass mark.\nDetail\n10. Evidence table: claim | number | source | grade, in <details>. Then sources.\n\nLimitations deck, limitations.html, 9 to 12 slides\nOverview\n1. Title: \"Should we build <product>?\", verdict pill, one sentence answer.\n2. The verdict in 30 seconds: verdict scale (pattern F), confidence, the single biggest reason.\n3. Every risk on one picture: risk map (pattern G), each risk named in plain words under it.\nEvidence\n4 to 8. One risk per slide, worst first: market, competition, technical, adoption, cost and unit economics, legal or regulatory if any. Takeaway heading, one visual (risk bars, a stat, a competitor price comparison), the evidence, and what would reduce it.\n9. What would kill it: kill criteria table: signal | kill if | check by.\n10. What would change our mind: the three facts, each with how to find it out.\nDetail\n11. Full risk register in <details> (risk | likelihood | impact | evidence | mitigation), how you scored, and sources.\n\nVerdict\nUse the research report's scale: Pursue, Pilot to test, Rethink, Park. Add a confidence (low, medium, high). If yours differs from the research verdict, say why on the verdict slide.\n\nEvidence\n- Every number cites its source: <a class=\"cite\" href=\"FULL_URL\">Publisher, Mon YYYY</a> <span class=\"grade g-B\">B</span>. The href is the exact page URL you or the research agent used, starting with https://. No source: write \"unverified\".\n- Name real competitors from the research. Never invent one.\n- A strength in the pitch deck that the limitations deck undercuts must be addressed in both.\n\nWriting\n- Slide headings state the takeaway as a sentence (\"Every rival charges under $40 a month\"), not a topic (\"Pricing\").\n- At most 5 short lines of text per slide. The visual carries the point.\n- Each slide has <aside class=\"notes\"> with 2 to 4 sentences of speaker notes. Hidden on screen; they drive narration later.\n- Load Plain Writing before you write the prose.\n\nTemplate rules\n- Use the template below as it is for both decks. Keep the style block, header, nav, the Spindle script and the slide script unchanged. Fill every {{placeholder}}, repeat slides as needed, delete blocks you have nothing for.\n- Light mode only. Never add colours, fonts, libraries, images other than the screenshots, or external scripts and styles. Never use the Telstra logo; the Spindle mark is the brand. This template overrides any look the design skills suggest.\n- Copy the screenshots next to the decks and reference them with relative paths.\n- Colours (defined in the template): ink #0A0F24, Telstra blue #0D54FF for what matters, deep blue #0A2FA8, soft blue #E8EEFF, grey #9AA3B5 for context, green #0A8A4A good, gold #B7791F caution, red #D0021B bad, amber #F44E1A for the Spindle mark only.\n- Charts are hand-drawn inline SVG from the patterns below, viewBox with width=\"100%\". Label values on the chart. Every chart has a source line under it.\n\nTemplate\n<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>{{Product}} | {{Pitch deck or Limitations}}</title>\n<base target=\"_blank\">\n<style>\n:root{--ink:#0A0F24;--muted:#5A6275;--line:#E3E6EE;--soft:#F5F7FB;--blue:#0D54FF;--deep:#0A2FA8;--blue-soft:#E8EEFF;--green:#0A8A4A;--gold:#B7791F;--red:#D0021B}\n*{box-sizing:border-box}html{-webkit-print-color-adjust:exact;print-color-adjust:exact}\nbody{margin:0;min-height:100vh;display:flex;flex-direction:column;background:#fff;color:var(--ink);font:16px/1.55 Inter,system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif}\na{color:var(--blue)}a:hover{text-decoration:none}\nheader{display:flex;align-items:center;gap:12px;padding:12px 32px;border-bottom:1px solid var(--line)}\n#spindle{width:56px;height:35px;flex:none}.brand b{display:block;letter-spacing:-.01em}.brand small{color:var(--muted);font-size:11px}\nheader .meta{margin-left:auto;font-size:12px;color:var(--muted);text-align:right}\n#bar{height:3px;width:0;background:var(--blue);transition:width .3s}\nmain{flex:1;display:flex}\n[data-slide]{flex:1;min-width:0;width:100%;max-width:1100px;margin:0 auto;padding:40px 48px;display:flex;flex-direction:column;justify-content:center;animation:in .35s ease}\n[data-slide][hidden]{display:none}\n@keyframes in{from{transform:translateY(8px)}}\n.cover{background:radial-gradient(ellipse at 90% 10%,var(--blue-soft),#fff 60%);max-width:none;padding-left:max(48px,calc((100% - 1004px)/2))}\n.kicker{font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--blue)}\nh1{font-size:46px;line-height:1.1;letter-spacing:-.02em;margin:8px 0 18px;max-width:880px}\nh2{font-size:30px;line-height:1.2;letter-spacing:-.015em;margin:6px 0 8px;max-width:900px}\nh3{font-size:16px;margin:0 0 8px;line-height:1.3}\n.sub{color:var(--muted);margin:0 0 22px;max-width:760px}.lead{font-size:20px;max-width:720px;margin:16px 0 0}\n.pill{display:inline-block;font-weight:800;font-size:12px;letter-spacing:.06em;text-transform:uppercase;padding:6px 14px;border-radius:999px}\n.pill.pursue{background:#E3F4EA;color:var(--green)}.pill.pilot{background:var(--blue-soft);color:var(--blue)}.pill.rethink{background:#FBF1DE;color:var(--gold)}.pill.park{background:#FCE6E8;color:var(--red)}\n.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}\n.tile{background:#fff;border:1px solid var(--line);border-radius:10px;padding:14px 16px;box-shadow:0 2px 10px rgba(10,15,36,.07)}\n.tile .l{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}\n.tile .v{font-size:28px;font-weight:800;line-height:1.2;margin-top:2px}.tile .s{font-size:12px;color:var(--muted)}\n.good{color:var(--green)}.mid{color:var(--gold)}.bad{color:var(--red)}\n.card{border:1px solid var(--line);border-radius:10px;padding:18px;background:#fff}\n.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;align-items:center}\n.stat{font-size:64px;font-weight:800;color:var(--blue);line-height:1;letter-spacing:-.02em}\n.src{font-size:12px;color:var(--muted);margin-top:10px}\n.cite{font-size:12px;white-space:nowrap}\n.grade{display:inline-block;font-size:10px;font-weight:800;border-radius:4px;padding:1px 6px;vertical-align:1px}\n.g-A{background:#E3F4EA;color:var(--green)}.g-B{background:var(--blue-soft);color:var(--blue)}.g-C{background:#FBF1DE;color:var(--gold)}.g-D{background:#FCE6E8;color:var(--red)}\n.chips{display:flex;flex-wrap:wrap;align-items:center;gap:8px;font-size:14px}\n.chip{background:var(--soft);border:1px solid var(--line);border-radius:8px;padding:8px 12px}.chip b{display:block;font-size:18px}\n.chip.total{background:var(--blue);border-color:var(--blue);color:#fff}\n.shot{display:block;width:100%;border:1px solid var(--line);border-radius:10px;box-shadow:0 8px 30px rgba(10,15,36,.10)}\n.steps{list-style:none;counter-reset:s;padding:0;margin:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px}\n.steps li{counter-increment:s;border-top:3px solid var(--blue);padding-top:14px}\n.steps li:before{content:counter(s);display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--blue);color:#fff;font-weight:800;margin-bottom:10px}\n.steps b{display:block}.steps span{font-size:14px;color:var(--muted)}\nblockquote{margin:0;padding:12px 16px;border-left:4px solid var(--blue);background:var(--soft);border-radius:0 8px 8px 0}\nul.plain{margin:0;padding-left:20px}ul.plain li{margin-bottom:6px}\ntable{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:8px 10px;border-bottom:1px solid var(--line);vertical-align:top}\nth{background:var(--soft);font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted)}\ndetails{margin-top:12px;border:1px solid var(--line);border-radius:10px;padding:10px 16px;max-height:60vh;overflow:auto}\nsummary{cursor:pointer;font-weight:600;color:var(--blue)}\naside.notes{display:none}\n.fine{margin-top:24px;font-size:12px;color:var(--muted)}\nnav{display:flex;align-items:center;gap:10px;padding:10px 32px;border-top:1px solid var(--line);font-size:13px;color:var(--muted)}\nnav .layer{margin-right:auto;font-weight:700;letter-spacing:.06em;text-transform:uppercase;font-size:11px;color:var(--blue)}\nnav button{font:inherit;color:var(--ink);background:#fff;border:1px solid var(--line);border-radius:8px;padding:6px 14px;cursor:pointer}\nnav button:hover{border-color:var(--blue);color:var(--blue)}nav button:disabled{opacity:.4;cursor:default}\n@media(max-width:700px){header,nav{padding-left:16px;padding-right:16px}[data-slide],.cover{padding:24px 16px;justify-content:flex-start}h1{font-size:30px}h2{font-size:23px}.stat{font-size:44px}header .meta{display:none}}\n@media print{header,nav,#bar{display:none}main{display:block}[data-slide],[data-slide][hidden]{display:flex;min-height:100vh;break-after:page;animation:none}details{max-height:none}}\n</style></head><body>\n<header>\n  <canvas id=\"spindle\" aria-hidden=\"true\"></canvas>\n  <div class=\"brand\"><b>Spindle</b><small>Telstra Muru-D \u00b7 Innovation research</small></div>\n  <div class=\"meta\">{{Pitch deck or Limitations}}<br>{{D Mon YYYY}}</div>\n</header>\n<div id=\"bar\"></div>\n<main>\n\n  <section data-slide data-layer=\"Overview\" class=\"cover\">\n    <div class=\"kicker\">{{Pitch deck or Limitations}}</div>\n    <h1>{{Product name, or \"Should we build <product>?\"}}</h1>\n    <div><span class=\"pill {{pursue|pilot|rethink|park}}\">{{Verdict}}</span></div>\n    <p class=\"lead\">{{One sentence: the promise, or the answer and the main reason.}}</p>\n    <aside class=\"notes\">{{2 to 4 sentences.}}</aside>\n  </section>\n\n  <section data-slide data-layer=\"Overview\">\n    <div class=\"kicker\">{{Short label}}</div>\n    <h2>{{Takeaway sentence}}</h2>\n    <div class=\"grid2\">\n      <div><div class=\"stat\">{{1 in 4}}</div><p>{{What the number means, in plain words.}}</p>\n        <div class=\"src\"><a class=\"cite\" href=\"{{https://exact/page}}\">{{Publisher, Mon YYYY}}</a> <span class=\"grade g-{{B}}\">{{B}}</span></div></div>\n      <blockquote>{{A quote or a one-line scenario.}}</blockquote>\n    </div>\n    <aside class=\"notes\">{{2 to 4 sentences.}}</aside>\n  </section>\n\n  <section data-slide data-layer=\"Evidence\">\n    <div class=\"kicker\">{{Short label}}</div>\n    <h2>{{Takeaway sentence}}</h2>\n    <p class=\"sub\">{{What the visual shows, and the date}}</p>\n    <div class=\"card\">\n      {{SVG from a pattern below, or <img class=\"shot\" src=\"screenshots/x.png\" alt=\"...\">}}\n      <div class=\"src\">Source: <a class=\"cite\" href=\"{{https://exact/page}}\">{{Publisher, Mon YYYY}}</a> <span class=\"grade g-{{A}}\">{{A}}</span></div>\n    </div>\n    <aside class=\"notes\">{{2 to 4 sentences.}}</aside>\n  </section>\n\n  <section data-slide data-layer=\"Detail\">\n    <div class=\"kicker\">Detail</div>\n    <h2>{{Takeaway sentence}}</h2>\n    <details open><summary>{{Show the full table}}</summary>\n      <table><tr><th>{{Column}}</th><th>Source</th></tr>\n        <tr><td>{{Value}}</td><td><a class=\"cite\" href=\"{{https://exact/page}}\">{{Publisher, Mon YYYY}}</a> <span class=\"grade g-{{C}}\">{{C}}</span></td></tr></table>\n    </details>\n    <details><summary>Sources</summary>\n      <ol><li><a href=\"{{https://exact/page}}\">{{Title, Publisher, D Mon YYYY}}</a> <span class=\"grade g-{{A}}\">{{A}}</span></li></ol>\n    </details>\n    <p class=\"fine\">Spindle \u00b7 Telstra Muru-D \u00b7 Prepared by the Scrutinizer agent on {{D Mon YYYY}} \u00b7 Sources graded A to D.</p>\n    <aside class=\"notes\">{{2 to 4 sentences.}}</aside>\n  </section>\n\n</main>\n<nav><span class=\"layer\" id=\"layer\"></span><button id=\"prev\" aria-label=\"Previous slide\">\u2190</button><span id=\"count\"></span><button id=\"next\" aria-label=\"Next slide\">\u2192</button></nav>\n<script>\n(()=>{const S=[...document.querySelectorAll(\"[data-slide]\")],L=document.getElementById(\"layer\"),C=document.getElementById(\"count\"),B=document.getElementById(\"bar\"),P=document.getElementById(\"prev\"),N=document.getElementById(\"next\");let i=0;\nfunction go(k){i=Math.max(0,Math.min(S.length-1,k));S.forEach((s,j)=>s.hidden=j!==i);L.textContent=S[i].dataset.layer||\"\";C.textContent=(i+1)+\" / \"+S.length;B.style.width=(i+1)/S.length*100+\"%\";P.disabled=i===0;N.disabled=i===S.length-1;history.replaceState(null,\"\",\"#\"+(i+1))}\nP.onclick=()=>go(i-1);N.onclick=()=>go(i+1);\naddEventListener(\"keydown\",e=>{if(e.key===\" \"&&e.target.closest(\"button,summary,a\"))return;if([\"ArrowRight\",\"PageDown\",\" \"].includes(e.key)){e.preventDefault();go(i+1)}if([\"ArrowLeft\",\"PageUp\"].includes(e.key)){e.preventDefault();go(i-1)}});\nlet x0=null;addEventListener(\"touchstart\",e=>x0=e.touches[0].clientX,{passive:true});addEventListener(\"touchend\",e=>{if(x0===null)return;const d=e.changedTouches[0].clientX-x0;if(Math.abs(d)>50)go(i+(d<0?1:-1));x0=null});\ngo((parseInt(location.hash.slice(1))||1)-1)})();\n</script>\n<script>\n(()=>{const cv=document.getElementById(\"spindle\"),ctx=cv.getContext(\"2d\"),T=1.5,S=2,Q=.7;let w,h;\nfunction size(){const r=cv.getBoundingClientRect(),d=devicePixelRatio||1;w=r.width;h=r.height;cv.width=w*d;cv.height=h*d;ctx.setTransform(d,0,0,d,0,0)}\nfunction draw(t){ctx.clearRect(0,0,w,h);const cy=h/2,R=h*.38,ph=t/1000*1.6,n=Math.floor(w/S),pts=[];\nfor(let i=0;i<=n;i++){const u=i/n,r=R*Math.pow(Math.sin(Math.PI*u),.8);for(let k=0;k<2;k++){const th=u*T*Math.PI*2-ph+k*Math.PI;pts.push([i*S,cy+r*Math.cos(th),Math.sin(th)])}}\npts.sort((a,b)=>a[2]-b[2]);ctx.fillStyle=\"#F44E1A\";ctx.globalAlpha=.18;for(let i=0;i<=n;i+=2)ctx.fillRect(i*S-Q,cy-Q,2*Q,2*Q);\nfor(const[x,y,z]of pts){const s=(2+(z+1)*1.25)*Q;ctx.globalAlpha=.25+(z+1)*.375;ctx.fillRect(x-s/2,y-s/2,s,s)}ctx.globalAlpha=1}\nsize();if(matchMedia(\"(prefers-reduced-motion: reduce)\").matches)draw(0);else{const loop=t=>{draw(t);requestAnimationFrame(loop)};requestAnimationFrame(loop)}})();\n</script>\n</body></html>\n\nBuilding blocks. Copy the shape, replace the numbers, keep the colours.\n\nTiles (Overview slides): <div class=\"tiles\"><div class=\"tile\"><div class=\"l\">{{Do people want it?}}</div><div class=\"v good\">{{4/5}}</div><div class=\"s\">{{High confidence}}</div></div></div>\nScreenshot beside benefits: <div class=\"grid2\"><img class=\"shot\" src=\"screenshots/home.png\" alt=\"{{what it shows}}\"><ul class=\"plain\"><li>{{Benefit}}</li></ul></div>\nSteps: <ol class=\"steps\"><li><b>{{Step}}</b><span>{{What happens}}</span></li></ol>\nFormula chips: <div class=\"chips\"><div class=\"chip\"><b>62,000</b>firms</div>\u00d7<div class=\"chip\"><b>12%</b>adopt</div>\u00d7<div class=\"chip\"><b>$1,080</b>a year</div>=<div class=\"chip total\"><b>$8.0M</b>a year</div></div>\n\nA. Score or risk bars: one row each, 120 units per point (5 = 600 of the 730 track). Fill green 4 to 5, gold 3, red 1 to 2 for scores. For risk severity flip it: red 4 to 5, gold 3, grey 1 to 2. Sort worst first.\n<svg viewBox=\"0 0 760 130\" width=\"100%\" role=\"img\" aria-label=\"Risk severity\">\n  <g font-size=\"14\" fill=\"#0A0F24\">\n    <text x=\"0\" y=\"24\" font-weight=\"700\">People may not switch 4/5 <tspan font-weight=\"400\" fill=\"#5A6275\">Adoption</tspan></text><text x=\"730\" y=\"24\" text-anchor=\"end\" fill=\"#5A6275\">Medium confidence</text>\n    <rect x=\"0\" y=\"34\" width=\"730\" height=\"18\" rx=\"9\" fill=\"#EEF1F6\"/><rect x=\"0\" y=\"34\" width=\"480\" height=\"18\" rx=\"9\" fill=\"#D0021B\"/>\n    <text x=\"0\" y=\"84\" font-weight=\"700\">Rivals can copy it fast 3/5 <tspan font-weight=\"400\" fill=\"#5A6275\">Competition</tspan></text><text x=\"730\" y=\"84\" text-anchor=\"end\" fill=\"#5A6275\">High confidence</text>\n    <rect x=\"0\" y=\"94\" width=\"730\" height=\"18\" rx=\"9\" fill=\"#EEF1F6\"/><rect x=\"0\" y=\"94\" width=\"360\" height=\"18\" rx=\"9\" fill=\"#B7791F\"/>\n  </g>\n</svg>\n\nB. Market size, nested circles. Not to scale: say so in the sub line.\n<svg viewBox=\"0 0 420 300\" width=\"100%\" style=\"max-width:420px\" role=\"img\" aria-label=\"Market size\">\n  <circle cx=\"210\" cy=\"150\" r=\"140\" fill=\"#E8EEFF\"/><circle cx=\"210\" cy=\"192\" r=\"96\" fill=\"#B9CCFF\"/><circle cx=\"210\" cy=\"238\" r=\"50\" fill=\"#0D54FF\"/>\n  <text x=\"210\" y=\"42\" text-anchor=\"middle\" font-size=\"13\" fill=\"#0A2FA8\" font-weight=\"700\">Everyone $1.2B</text><text x=\"210\" y=\"60\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5A6275\">TAM</text>\n  <text x=\"210\" y=\"122\" text-anchor=\"middle\" font-size=\"13\" fill=\"#0A2FA8\" font-weight=\"700\">We can reach $410M</text><text x=\"210\" y=\"140\" text-anchor=\"middle\" font-size=\"11\" fill=\"#0A2FA8\">SAM</text>\n  <text x=\"210\" y=\"236\" text-anchor=\"middle\" font-size=\"14\" fill=\"#fff\" font-weight=\"800\">We win $24M</text><text x=\"210\" y=\"254\" text-anchor=\"middle\" font-size=\"11\" fill=\"#fff\">SOM, by year 3</text>\n</svg>\n\nD. Positioning map: the two axes that matter in this market, rivals in grey with names and prices, our spot in blue.\n<svg viewBox=\"0 0 900 300\" width=\"100%\" role=\"img\" aria-label=\"Competitor map\">\n  <line x1=\"60\" y1=\"260\" x2=\"880\" y2=\"260\" stroke=\"#C9CEDA\"/><line x1=\"60\" y1=\"20\" x2=\"60\" y2=\"260\" stroke=\"#C9CEDA\"/>\n  <text x=\"470\" y=\"290\" font-size=\"12\" fill=\"#5A6275\" text-anchor=\"middle\">{{x axis}} \u2192</text>\n  <text x=\"24\" y=\"140\" font-size=\"12\" fill=\"#5A6275\" text-anchor=\"middle\" transform=\"rotate(-90 24 140)\">{{y axis}} \u2192</text>\n  <circle cx=\"150\" cy=\"210\" r=\"11\" fill=\"#9AA3B5\"/><text x=\"168\" y=\"214\" font-size=\"12\" fill=\"#0A0F24\">Rival A $29</text>\n  <circle cx=\"700\" cy=\"80\" r=\"14\" fill=\"#0D54FF\"/><text x=\"720\" y=\"85\" font-size=\"14\" font-weight=\"700\" fill=\"#0D54FF\">{{Product}}</text>\n</svg>\n\nF. Verdict scale: four segments, Park to Pursue. The chosen one is solid, the others faded. The marker sits over the chosen segment's centre: x = 93 + position x 190 (Park 0, Rethink 1, Pilot to test 2, Pursue 3).\n<svg viewBox=\"0 0 760 110\" width=\"100%\" role=\"img\" aria-label=\"Verdict: Pilot to test\">\n  <g opacity=\".22\"><rect x=\"0\" y=\"44\" width=\"186\" height=\"18\" rx=\"9\" fill=\"#D0021B\"/><rect x=\"190\" y=\"44\" width=\"186\" height=\"18\" rx=\"9\" fill=\"#B7791F\"/><rect x=\"570\" y=\"44\" width=\"186\" height=\"18\" rx=\"9\" fill=\"#0A8A4A\"/></g>\n  <rect x=\"380\" y=\"44\" width=\"186\" height=\"18\" rx=\"9\" fill=\"#0D54FF\"/>\n  <path d=\"M463 24 L483 24 L473 38 Z\" fill=\"#0A0F24\"/><text x=\"473\" y=\"14\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\" fill=\"#0A0F24\">Our verdict</text>\n  <g font-size=\"13\" text-anchor=\"middle\" fill=\"#5A6275\"><text x=\"93\" y=\"86\">Park</text><text x=\"283\" y=\"86\">Rethink</text><text x=\"473\" y=\"86\" font-weight=\"700\" fill=\"#0D54FF\">Pilot to test</text><text x=\"663\" y=\"86\">Pursue</text></g>\n</svg>\n(The triangle's points are x - 10, x + 10 and x.)\n\nG. Risk map: likelihood 1 to 5 left to right, x = 60 + (likelihood - 1) x 110. Impact 1 to 5 bottom to top, y = 320 - (impact - 1) x 75. Red top-right is \"act now\". Dot colour by likelihood x impact: 15 or more red, 8 to 14 gold, under 8 grey. Number dots R1, R2 ... and list them under the map in plain words.\n<svg viewBox=\"0 0 520 370\" width=\"100%\" style=\"max-width:560px\" role=\"img\" aria-label=\"Risk map\">\n  <rect x=\"280\" y=\"20\" width=\"220\" height=\"150\" fill=\"#FCE6E8\"/><text x=\"490\" y=\"40\" font-size=\"12\" fill=\"#D0021B\" font-weight=\"700\" text-anchor=\"end\">Act now</text>\n  <line x1=\"60\" y1=\"320\" x2=\"500\" y2=\"320\" stroke=\"#C9CEDA\"/><line x1=\"60\" y1=\"20\" x2=\"60\" y2=\"320\" stroke=\"#C9CEDA\"/>\n  <text x=\"280\" y=\"350\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5A6275\">How likely \u2192</text>\n  <text x=\"24\" y=\"170\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5A6275\" transform=\"rotate(-90 24 170)\">How bad if it happens \u2192</text>\n  <circle cx=\"390\" cy=\"95\" r=\"14\" fill=\"#D0021B\"/><text x=\"390\" y=\"100\" text-anchor=\"middle\" font-size=\"11\" fill=\"#fff\" font-weight=\"700\">R1</text>\n  <circle cx=\"280\" cy=\"170\" r=\"14\" fill=\"#B7791F\"/><text x=\"280\" y=\"175\" text-anchor=\"middle\" font-size=\"11\" fill=\"#fff\" font-weight=\"700\">R2</text>\n  <circle cx=\"170\" cy=\"245\" r=\"14\" fill=\"#9AA3B5\"/><text x=\"170\" y=\"250\" text-anchor=\"middle\" font-size=\"11\" fill=\"#fff\" font-weight=\"700\">R3</text>\n</svg>\n\nKill criteria: <table><tr><th>Signal</th><th>Kill if</th><th>Check by</th></tr><tr><td>{{Waitlist sign-ups from a $2k ad test}}</td><td>{{Under 3% of visitors}}</td><td>{{Week 2}}</td></tr></table>\n\nOther numbers: horizontal bars sorted largest first, grey with the important one in blue, for comparing; a line for trends over time.\n\nCheck, then serve\n1. write_file deck.html and limitations.html in your own directory.\n2. read_file each back and check: no {{ left; every slide has data-layer and a notes aside; every a.cite href starts with https:// and is a real page; every heading is a sentence; slide count in range; no colours outside the palette; screenshots referenced exist.\n3. next_free_port, then run_command in the background: python3 -m http.server <port> --bind 0.0.0.0 --directory <your directory>.\n4. publish_preview twice on that port: path /deck.html titled \"<Product> pitch deck\", path /limitations.html titled \"<Product> limitations\".\n\nReply with both URLs, the verdict and confidence, and the three facts. Nothing else.",
  "description": "Load before building the pitch deck or the limitations deck."
}$p$::jsonb,
   true,
   70);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$design_taste$p$,
   $p$Design Taste$p$,
   $p$Reads the brief, picks a design direction and avoids the looks every AI ships.$p$,
   $p${
  "text": "Adapted from taste-skill by Leon Lin (github.com/Leonxlnx/taste-skill, MIT).\n\nMost generated design is bad because the model jumps to a default look instead of reading the brief. Read first, then decide.\n\nDelivery rules from other skills win: if the deliverable is one self-contained HTML file with no installs, everything below happens inside that file. Interaction patterns stay familiar; the visual layer is where you commit.\n\n1. Read the brief\nBefore any code, write one line: \"Reading this as: <page kind> for <audience>, with a <vibe> language, leaning toward <aesthetic family>.\"\nSignals: the kind of surface (landing page, app screen, pitch deck), the words the user used for the feel, products or references they named, the audience, brand assets that already exist, and quiet constraints (public sector, regulated, kids, accessibility-first). Quiet constraints override taste. The audience picks the aesthetic, not you.\nIf the read genuinely forks, ask one question. If you can infer it, don't ask.\n\n2. Set three dials, 1 to 10\n- Variance: 1 is perfect symmetry, 10 is asymmetric and art-directed.\n- Motion: 1 is static, 10 is choreographed.\n- Density: 1 is gallery-airy, 10 is cockpit-packed.\nDefaults: marketing page 8/6/4, calm or minimal 5/3/3, trust-first or public sector 3/2/5, pitch deck 6/4/3, app screen 4/4/6. State the values you chose. Above variance 4, asymmetric layouts collapse to one column under 768px.\n\n3. Refuse the AI defaults\nUnless the brief asks for them by name:\n- No purple or blue glow gradients, no neon outer glows, no gradient text on headings.\n- No centred hero over a dark mesh. No row of three identical feature cards.\n- No Inter as the automatic choice. No Fraunces or Instrument Serif. Serif only when the brand is genuinely editorial, luxury or heritage and you can say why this serif fits this brand. \"Creative brief means serif\" is the most tested AI tell.\n- No warm cream background with brass, clay or oxblood accents and espresso text as the reflex for premium or craft products.\n- No pure #000 or #fff. Use an off-black and an off-white.\n- No emoji or unicode glyphs as icons. Use one icon set, inline SVG copied from a real library (Phosphor, Tabler), one stroke width throughout.\n- No fake product screenshots built from div rectangles. Use a real screenshot, a real mini component, or none.\n- No generic names or numbers: no Acme, no John Doe, no 99.99%. Invented demo data is labelled as sample.\n- No filler verbs: elevate, seamless, unleash, next-gen, revolutionize.\n- No em dashes anywhere visible. Use a comma, colon, full stop or hyphen.\n\n4. Colour, type and shape locks\n- One accent colour, used the same way on every section. Saturation under 80% unless the brand says otherwise.\n- One theme per page. Sections don't flip from dark to light mid-scroll.\n- One corner radius system: all sharp, all soft (12 to 16px), or pill buttons with a written rule for everything else.\n- Pair type deliberately. Emphasis inside a headline uses the italic or bold of the same family, never a second family.\n- Italic display type with descenders (g j p q y) needs line-height 1.1 or more, or the descenders clip.\n\n5. Layout discipline\n- The opening screen fits the viewport: headline at most 2 lines, subtext at most 20 words, the main action visible without scrolling.\n- At most 4 text elements in a hero: optional small label, headline, subtext, actions (1 primary, at most 1 secondary).\n- Small uppercase labels above headings: at most one per three sections.\n- Never repeat a section layout family on one page. Never three image-plus-text zigzags in a row.\n- Cards only when elevation means hierarchy. Otherwise group with space or a single divider.\n- A grid has exactly as many cells as you have content. No empty tiles.\n- More than 5 items is a different component (grouped columns, tabs, scroll-snap row), not a longer list.\n\n6. States and contrast\nEvery interactive surface has loading, empty and error states, not just the happy path. Every button label passes 4.5:1 against its fill. Button labels fit on one line and one intent has one label across the page (\"Get started\" everywhere, not three variants).\n\n7. Pre-flight\nBefore handing off, check: design read stated, dials stated, zero em dashes, one theme, one accent, one radius system, hero fits, label count, no repeated layout family, no default-AI tells from step 3, contrast on every button and input, states present. If any check fails, fix it before you reply.",
  "description": "Load before choosing the look of a page, prototype or deck: layout, type, colour, imagery."
}$p$::jsonb,
   true,
   71);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$impeccable$p$,
   $p$Impeccable$p$,
   $p$Commits to a bold visual direction and holds a craft floor while building it.$p$,
   $p${
  "text": "Adapted from Impeccable by Paul Bakaus (github.com/pbakaus/impeccable, Apache-2.0).\n\nApproach every design task as an award-winning design director: a clear point of view, real understanding of the user, and finished craft. Safe and timid is the failure mode.\n\nPrinciples\n- Finish it. The deliverable is complete except for assets only the user can provide.\n- The brief wins. Honour any pinned aesthetic, era, font or palette, even when it matches a pattern this skill warns about.\n- Refinement keeps the existing identity, behaviour and copy. A redesign keeps the product's facts and function but replaces the old look rather than polishing it.\n- Verify in bounded passes: build fully, inspect once at desktop and mobile width, fix everything in one batch, confirm once more, stop.\n\nPick the mode from the surface, not the product\n- Persuade (landing pages, pitch decks): the visitor decides and acts. Earn attention, make the offer clear, show the main action.\n- Operate (app screens, dashboards, settings): the visitor completes a task. Scanability, consistency and familiar controls outrank expression. Brand lives in precise details.\n- Read (docs, reports, articles): the visitor understands something. Structure for comprehension, then make it worth staying in.\n- Experience (portfolios, showcases): the work leads from the first screen; the interface recedes.\n\nCommit to a world\n- Name the product's one unique mechanism, the audience's real scene, and what this first screen must prove.\n- Pick a colour strategy before colours: Restrained (neutrals plus one accent, the default for Operate and Read), Committed (one saturated colour carries 30 to 60% of the surface), Full palette (3 or 4 named roles), or Drenched (the surface is the colour). Persuade surfaces may take the bolder strategies.\n- Light or dark is never a default. Write one sentence of physical scene (who uses this, where, under what light) and let it decide.\n- Choose faces like objects from the subject's world. Operate and Read are well served by good system or workhorse UI faces. For Persuade, these defaults mean you stopped looking: Fraunces, Playfair Display, Cormorant, Lora, Syne, Space Grotesk, Space Mono, IBM Plex, DM Sans, Outfit, Plus Jakarta Sans, Inter as display. If the file must be self-contained, embed the face or use a deliberate system stack; never fall back to Arial by accident.\n- Self-check: AI interfaces cluster on three looks: cream ground with a serif display and a terracotta accent; near-black with one neon accent and glowing edges; editorial hairlines with italic serif and tiny tracked mono labels. Where the brief leaves the look open, landing on one of these means rework.\n- The first screen is a thesis, not a header. Show the mechanism at work. Prove, don't claim: specific content a competitor could not copy-paste. Claims (prices, customers, benchmarks) come from supplied facts only; illustrative data is labelled as sample.\n\nCraft floor: check the built result, not the intention\n- Contrast: body text 4.5:1, large text 3:1. On coloured surfaces tint secondary text from that hue, never plain grey.\n- Depth: shadows have an offset and a soft blur. A zero-offset coloured halo is decoration.\n- Spacing: tight inside groups, generous between them, more space above a heading than below it.\n- Type: body line length 65 to 75 characters, display text at most 6rem, letter-spacing no tighter than -0.04em, obvious steps in size and weight.\n- Motion: one authored moment, not the same fade-in on every section. Ease out from an already-visible default.\n- States: hover, focus, disabled, loading, error, empty. Real content, working controls.\n- Browser surfaces carry the design too: text selection colour, caret, focus rings, scrollbars, link underline offset, tabular numerals in data.\n- Copy: controls name their action; errors name the problem and the recovery.\n- Coverage: every requirement in the brief is present and findable within seconds.\n\nRefuse unless the brief earns it\n- Same-size cards of icon, heading and text as the page structure. Cards nested in cards.\n- The hero-metric template: big number, small label, supporting stats.\n- A small label above every heading. Section numbers like 01 / 02 / 03 unless the order is information.\n- A modal for a task that needs no interruption.\n- Gradient text. Glass and blur as decoration. Coloured left or right border stripes on cards and callouts.\n- Hard offset block shadows outside a genuinely neo-brutalist world.\n- Sparklines, progress rings and rounded rectangles standing in for real content.\n- Monospace as a costume for \"technical\". Emoji or unicode as an icon system.\n- Stripe or grid-line backgrounds with nothing measured underneath.\n\nWhen torn between refined and committed, commit.",
  "description": "Load before building or critiquing any interface, page or deck, and again before you call it done."
}$p$::jsonb,
   true,
   72);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$emil_design_eng$p$,
   $p$Emil Design Engineering$p$,
   $p$Animation and interaction polish: when to animate, easing, timing, press feedback.$p$,
   $p${
  "text": "Adapted from emil-design-eng by Emil Kowalski (github.com/emilkowalski/skills, MIT).\n\nUnseen details compound. Most users never notice them consciously; together they are why an interface feels right. Beauty is leverage: good defaults and good motion are real differentiators.\n\nShould this animate at all?\n- Seen 100+ times a day (shortcuts, command palette): never animate.\n- Tens of times a day (hover, list navigation): remove or drastically reduce.\n- Occasional (modals, drawers, toasts): standard animation.\n- Rare or first time (onboarding, celebrations): room for delight.\nNever animate keyboard-initiated actions. Every animation needs a purpose: spatial consistency, state change, explanation, feedback, or preventing a jarring jump. \"It looks cool\" on something seen often is not a purpose.\n\nEasing\n- Entering or exiting: ease-out. Moving on screen: ease-in-out. Hover or colour change: ease. Constant motion: linear.\n- Never ease-in for UI. It delays the first movement, the moment the user watches most.\n- Built-in CSS curves are weak. Use custom ones:\n  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);\n  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);\n  --ease-drawer: cubic-bezier(0.32, 0.72, 0, 1);\n\nDuration\nPress feedback 100 to 160ms. Tooltips and small popovers 125 to 200ms. Dropdowns 150 to 250ms. Modals and drawers 200 to 500ms. UI animation stays under 300ms; a 180ms dropdown feels faster than a 400ms one. Exits are faster than entrances.\n\nComponent details\n- Pressables scale to 0.97 on :active with a 160ms ease-out transform. Keep it between 0.95 and 0.98.\n- Never animate from scale(0). Start at scale(0.95) with opacity 0.\n- Popovers scale from their trigger, not the centre. Modals stay centred.\n- Tooltips wait before the first one opens; once one is open, neighbours open instantly with no animation.\n- Use transitions, not keyframes, for anything triggered rapidly. Transitions retarget mid-flight; keyframes restart from zero.\n- When a crossfade still looks like two objects swapping, add filter: blur(2px) during the transition. Keep blur under 20px.\n- Animate entry without JS using @starting-style.\n- translateY(100%) moves an element by its own height, whatever that height is. Prefer percentages to hard-coded pixels.\n- clip-path: inset() is a strong animation tool: reveals, hold-to-confirm fills, tab highlights, comparison sliders.\n- Stagger groups by 30 to 80ms per item. Never block interaction while a stagger plays.\n- Slow where the user is deciding (hold-to-delete: 2s linear), fast where the system responds (release: 200ms ease-out).\n- Match motion to personality: a playful component can bounce a little (0.1 to 0.3), a professional tool should be crisp.\n\nDrag and gesture\nDismiss on velocity, not only distance: a flick over about 0.11 px/ms is enough. Past a boundary, add friction instead of a hard stop. Capture the pointer once dragging starts. Ignore extra touch points mid-drag.\n\nPerformance\nAnimate only transform and opacity; padding, margin, width and height trigger layout. Update transform on the element directly rather than a CSS variable on a parent with many children. CSS animations stay smooth when the main thread is busy; JS frame loops drop frames.\n\nAccessibility\nUnder prefers-reduced-motion, keep opacity and colour changes that aid understanding and remove movement. Gate hover effects behind @media (hover: hover) and (pointer: fine) so touch taps don't trigger them.\n\nReview format\nWhen reviewing UI, reply with one markdown table, columns Before | After | Why, one row per issue. Check for: transition: all, scale(0) entrances, ease-in on UI, centred popover origins, animated keyboard actions, UI durations over 300ms, ungated hover effects, keyframes on rapidly triggered elements, equal enter and exit speeds, and groups that appear all at once.",
  "description": "Load before adding any animation, transition or interactive feedback, and when reviewing how an interface feels."
}$p$::jsonb,
   true,
   73);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$market_sizing$p$,
   $p$Market Sizing$p$,
   $p$How to size TAM, SAM and SOM bottom-up first, build SOM, and show the working.$p$,
   $p${
  "text": "Size the market from the buyer up, check it from the top down, and show every input. A market size nobody can check is a guess with a dollar sign. Every input is a ledger row (Evidence Ledger), and sizing.py does all the arithmetic.\n\n0. Define the unit first\nWrite one line: \"<who pays> pays <what> for <what>, per year, in <geography>.\" Default geography is Australia unless the idea says otherwise.\n- Money in AUD, for an Australian financial year (FY2025-26 runs 1 July 2025 to 30 June 2026).\n- Record each input's data year (the year it measures) separately from its publish date.\n- Foreign currency: convert at the RBA average rate for the source's data year. The rate is a ledger input.\n- AUD from an older year: roll it forward with ABS CPI. The CPI values are ledger inputs.\n\n1. The layers\n- TAM today: every buyer of this kind of product x units per buyer x realised price. Realised price is what buyers actually pay, not list price. Size the category, not just our version. No adoption term in TAM.\n- Units must match the price unit: seat, site, firm or household. A per-seat price times a count of firms is wrong.\n- Expansion TAM (optional): new spend a new category creates beyond what buyers spend today. Example: Damodaran sized Uber against the taxi market; Gurley argued cheaper, faster rides would grow usage and replace some car ownership. Write it as a separate line with its own thesis and evidence. Never add it into TAM today.\n- SAM: the part of TAM this offer can serve today. One filter per line: segment, channels, geography, regulation. Each filter has a ledger id or says \"assumption\". Filters must not overlap: never cut the same buyers twice.\n- SOM: our revenue in year 3, from the build in step 5. Never a percentage of SAM.\n\n2. Order: bottom-up first\nBuild bottom-up before you search for any market-size report or headline total. A headline seen first anchors everything after it. Only then run top-down, as a ceiling and a check.\n\n3. Bottom-up\n- Businesses: ABS Counts of Australian Businesses (cat. 8165), employing businesses by ANZSIC division and employment size band. Never all businesses: about 65% are non-employing at June 2026.\n- People and households: ABS population, household counts, Census QuickStats.\n- Regulated groups: regulator registers where they fit (Ahpra practitioners, NDIS participants, ACMA reports, APRA and ASIC registers).\n- Price: competitors' pricing pages, dated. Annualise monthly prices. Use the tier the target buyer would choose.\n- Formula: buyers x units per buyer x realised price.\n\n4. Top-down\nTake a published total and narrow it with the SAM filters, one per line.\n- Market-report publishers (report catalogues and press-release wires) disagree 2-3x on the same market. Use them as bounds only, never as the base.\n- Collapse syndicated copies and co-owned publishers into one group.\n- Exclude any figure more than 2x a primary anchor for the same scope.\n\n5. Build SOM\nRevenue in year 3, built over 36 months, net of churn.\n- B2B: ramped sales reps x quota x attainment, or channel reach x conversion x annual contract value.\n- B2C: reach x funnel conversion x annual revenue per user x retention.\n- Telstra distribution enters as a channel-reach input with its own conversion assumption. Never assume it.\n- B2B churn floor: the ABS business exit rate, about 14% a year in 2025-26.\n- Benchmarks like rep ramp time vary across sources: range them, don't pick one.\n\nCross-check SOM three ways. Report each as pass or fail, with the numbers.\na. Category diffusion: under pooled Bass parameters (p 0.03, q 0.38), a new category reaches about 3.6% of eventual adopters in year 1, 8.5% in year 2 and 15% in year 3, across all vendors together. SOM must be a share of that, not of SAM. The parameters come mostly from consumer durables: an order-of-magnitude check, not a forecast.\nb. Peer: a named peer's revenue or customer count at the same age.\nc. Sum of shares: named competitors' revenue plus our SOM must fit inside SAM. If it doesn't, the market can't hold everyone's plans (Damodaran's big market delusion).\n\n6. Triangulate\nCompare the bottom-up and top-down base cases for SAM.\n- Within 2x: they agree. Lead with bottom-up.\n- More than 2x apart: one holds a bad assumption. Name the input that explains the gap and fix it. Never average the two.\n\n7. Ranges by driver\n- Each input gets its own sourced low and high. Assumptions get wide ranges.\n- All arithmetic runs in sizing.py (Evidence Ledger). Never type a computed number yourself.\n- Report the tornado's top two drivers from sizing.md: the inputs that swing the result most.\n- All lows together and all highs together are outer bounds. Label them \"outer bound\".\n\n8. Decision line\nSay whether the SOM range clears, misses or straddles the bar the brief gives. No bar given: place it on the Strategyzer opportunity scale (under $100k, $10M+, $100M+ revenue a year) and say which bar would change the verdict.\n\n9. Where to get Australian numbers\n- ABS 8165 Counts of Australian Businesses: employing businesses by ANZSIC division and size band, plus entries and exits. XLSX: download it in the sandbox. web_fetch cannot read XLSX or PDF and truncates at 20,000 characters.\n- ABS Data API: https://data.api.abs.gov.au/rest/ with format=csv. No key needed.\n- ABS 8167 Characteristics of Australian Business: share of businesses using a technology (cloud, AI, cyber security).\n- ATO taxation statistics on data.gov.au: businesses and income by industry and size.\n- ACMA communications reports: telco, internet and device use.\n- Ahpra registration data: practitioner counts by profession and state.\n- NDIS quarterly data: participants and payments. Links change: search first.\n- RBA exchange rate tables (CSV): historical AUD rates.\n- ABS CPI: the index for rolling old AUD forward.\n- Household Expenditure Survey: latest is 2015-16 and has no successor. Anything built on it is Low confidence.\n- IBISWorld and Statista are paywalled. A snippet figure is grade C at best.\nDon't hardcode volatile figures other than those dated above. Fetch current ones.\n\nOutput, in this order:\n- The unit line.\n- Layer table: Layer | Low | Base | High | Method, copied from sizing.md.\n- Expansion TAM line, if any, with its thesis.\n- Each formula written out with its numbers from sizing.md: \"62,000 firms x 1 site x $1,080 = $67M\".\n- The tornado's top two drivers.\n- The three SOM cross-checks, pass or fail.\n- Whether top-down and bottom-up agree.\n- The decision line.\n- Inputs table: Ledger id | Input | Low | Base | High | Source (publisher, date, full URL) | Grade (e.g. \"B2\"). Assumptions show \"assumption\" instead of a ledger id.\n\nRules: no number without a ledger id or an \"assumption\" label. Prefer A and B sources. Never round a guess into false precision: $8M, not $8,035,200.",
  "description": "Load before estimating how big a market is: TAM, SAM, SOM, revenue potential."
}$p$::jsonb,
   true,
   80);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$dvf_assessment$p$,
   $p$DVF Assessment$p$,
   $p$How to judge desirability, viability and feasibility on evidence, not opinion.$p$,
   $p${
  "text": "Judge an idea on three lenses. Score what the evidence shows, not what you believe. Opinion is not evidence.\n\nWho covers what\n- Project Scoping covers Feasibility.\n- Market Research covers Desirability and Viability, then assembles the full scorecard and verdict, taking Feasibility from the scoping agent's context. If that context is missing, do a short Feasibility pass yourself and label it \"provisional\".\n\nEach lens gets three things: a score 1-5, an evidence level 0-5, and a confidence.\n\nDesirability: do people want this?\nLook at: who has the problem, how often, how badly; what they do today (workarounds, spend, products used); competitors' traction (customers, revenue, funding); review volume and complaints; search interest; surveys.\n- 5: strong pull: competitors with large, growing paying bases, buyers already pay for workarounds, and target buyers have committed (letters of intent, deposits, pilots).\n- 4: clear demand: several competitors with real traction, the same complaint recurs across many reviews, buyers already spend on the problem.\n- 3: some demand: the problem is real but signals are thin, mixed, or come from a different segment.\n- 2: weak demand: few buyers spend on it today, signals are mostly opinion or forum noise, or competitors have struggled to sell.\n- 1: evidence against: buyers tried and dropped similar products, competitors closed for lack of demand, or the problem is rare or minor.\n\nViability: does it make money for Telstra?\nLook at: what buyers already pay for comparable products (pricing pages); SAM and SOM from Market Sizing; revenue model; unit economics (price, cost to serve, acquisition cost).\nAdaptability, a named sub-check: competitor moves, regulation, technology shifts and macro forces that could close the window. Write one line on it.\n- 5: buyers already pay prices that give unit economics at or above the benchmarks for this model, SOM clears the bar, and no adaptability risk threatens the window.\n- 4: comparable prices show willingness to pay, modelled unit economics meet benchmarks for this model, SOM is near or above the bar.\n- 3: money is possible but unproven: price or cost uncertain, SOM straddles the bar, or one adaptability risk could close the window.\n- 2: economics look weak: likely price below cost to serve, SOM well below the bar, or a strong competitor or regulatory shift is under way.\n- 1: evidence it can't make money: the price ceiling sits below cost to serve, the market is too small, or regulation blocks the model.\n\nViability benchmarks by business model. Label them as benchmarks, with the source:\n- LTV:CAC above 3 and CAC payback under 12 months (Skok, forEntrepreneurs).\n- 2025 median CAC payback about 20 months; median software gross margin 80% (Aleph x Benchmarkit).\n- Early AI-native companies run about 25-60% gross margin (Bessemer via SaaStr).\n- Pre-revenue ratios are always modelled: label them \"assumption\".\n- Don't fail a marketplace or hardware idea on SaaS margins. Use benchmarks for its own model, or say none were found.\n\nFeasibility: can Telstra build and deliver it?\nLook at the five TELOS checks:\n- Technology: the core technology, named, with its TRL 1-9 (1 idea, 4 lab prototype, 6 demonstrated in a relevant setting, 7 pilot in real use, 9 proven in market).\n- Cost to build and run: rough range to an MVP a real customer could use, and to run it.\n- Law and privacy: ACMA rules, the Privacy Act, sector rules (health, finance, critical infrastructure).\n- Operations: Telstra assets, platforms, partners, data and teams it relies on.\n- Schedule: dependencies, approvals and time to MVP.\nScore the lens, or each TELOS check on its own, with these anchors:\n- 5: ready: technology at TRL 8-9 in comparable products; Telstra already has the assets; no legal hurdle; cost and time fit a normal pilot.\n- 4: mostly ready: TRL 7, a known build path; minor dependencies or approvals with a known process.\n- 3: doable with work: TRL 5-6, or one key partner, approval, dataset or skill not yet secured, or cost and time at the edge of a pilot budget.\n- 2: hard: TRL 3-4, major unknowns, a significant legal or privacy hurdle, or cost and time well beyond a pilot budget.\n- 1: blocked: TRL 1-2, the law prohibits it, or a required asset or dataset doesn't exist.\nOverall Feasibility is the weakest TELOS check.\n\nEvidence level 0-5: what kind of evidence, say versus do\n- 0: none, or opinion.\n- 1: articles and reports about the market.\n- 2: what people say: surveys, interviews, forum complaints, published survey results.\n- 3: what people already do: competitor traction, review volume, search volume, prices buyers pay, fake door tests, waitlists.\n- 4: commitments: letters of intent, deposits, paid pilots.\n- 5: repeat paid use at the real price.\nDesk research reaches 3 at most. More sources raise agreement, not the level.\n\nConfidence\nUse Source Grading's rule (evidence x agreement). Then cap it: Desirability and Viability cannot be High below evidence level 4. Feasibility can be High from public evidence: specs, regulation text, working comparables.\nA score of 4 or 5 with Low confidence says so in the sentence that states it.\n\nTelstra strategic fit gate: Pass, Fail or Unclear, with the reason.\nPass when it uses Telstra's network, retail or business channels, customer base, brand or enterprise relationships, and fits where Telstra is heading. Fail when it uses none of them or works against Telstra's direction. Unclear when you can't tell from the evidence.\n\nBias guard\n- Score from research.md's evidence, not the founder's pitch.\n- Before scoring, write the bear case: \"Which lens most likely kills this, and why?\" One paragraph.\n- If the scores ignore something the bear case names, lower that lens's confidence.\n- LLMs lean optimistic. When in doubt, score lower.\n\nVerdict. Apply in order; the first rule that matches decides.\n1. Gate Fail: Park.\n2. A lens at 1 with Medium or High confidence, or two lenses at 2 with Medium or High confidence: Park.\n3. One lens at 2 with Medium or High confidence: Rethink. Say what would have to change.\n4. A lens at 1 or 2 with Low confidence means unknown, not bad: Pilot to test.\n5. Pursue only when every lens is 4 or more, no confidence is Low, the gate is Pass, and Desirability evidence level is 4 or more.\n6. Everything else: Pilot to test. Name the experiment.\n\"Unknown: insufficient evidence\" counts as Low in these rules.\nA desk-only pass never says Pursue.\n\nLikelihood words\nWhen you say how likely something is, use only these terms, with the number in brackets: remote (1-5%), very unlikely (5-20%), unlikely (20-45%), roughly even chance (45-55%), likely (55-80%), very likely (80-95%), almost certain (95-99%). Never put a confidence level and a likelihood term in the same sentence.\n\nRiskiest assumptions\nList 5 to 8. Each is written \"We believe that ...\", tagged D, V or F, with importance 1-5 (how badly the idea fails if it is false) and its evidence level now, 0-5. High importance with low evidence is where to test first.\nThe top three each get a Test Card:\n- Test: what to do.\n- Metric: what to measure.\n- Pass threshold: set before the test runs.\n- Rough cost and time.\n- The evidence level a pass would reach.\nPrefer B2B letters of intent and paid pilots: Telstra's channels make them cheap. Thresholds are internal defaults, say so. Example rule of thumb from practitioners: landing page CTA click-through above 10% is strong, under 3% is weak.\n\nOutput, in this order:\n- Scorecard table: Lens | Score /5 | Evidence level | Confidence | One-line reason with ledger ids.\n- Gate line: Pass, Fail or Unclear, and why.\n- Bear case paragraph.\n- Verdict and the reason in two sentences.\n- Assumptions table: # | We believe that ... | Lens | Importance | Evidence level | Test Card (top three only).",
  "description": "Load before judging whether an idea is worth pursuing: desirability, viability, feasibility, verdict, riskiest assumptions."
}$p$::jsonb,
   true,
   81);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$visual_report$p$,
   $p$Visual Report$p$,
   $p$The Telstra-style HTML report template and how to publish it.$p$,
   $p${
  "text": "Turn your finished research.md into report.html: a professional Telstra-style report in light mode, for a Telstra innovation lab team deciding whether an idea is worth pursuing. The markdown comes first. The report is a tuned view of it: no new claims.\n\nHow it reads: the first screen answers \"should we pursue this, and why?\" in 30 seconds. Each section down the page goes one level deeper. Sources come last.\n\nWrite for two readers on one page. The top must make sense to someone with no business or research background; the bottom must satisfy an expert researcher checking your working.\n- Top third (hero, tiles, first visuals): everyday words, short sentences, no jargon or acronyms. Say \"how many people could buy this\" before \"TAM\", \"would people want it, would it make money, can we build it\" before \"DVF\". If a term must appear, its plain meaning goes first and the term follows in small text: \"Customers we could realistically win (SOM)\".\n- Middle (findings, competitors, assumptions): plain words with the standard terms named once, each claim with its number and citation.\n- Bottom (inside <details>, inputs tables, method notes, sources): full expert detail. Formulas with every input, both sizing methods and why they agree or differ, scoring rubric, confidence reasoning, source grades. Precise terms are fine here.\n- Tile labels and section headings use plain words. Never open a section with an acronym.\n- Test the top third: would a new graduate in any team get the answer and the reason without asking you? If not, rewrite it.\n\nRules\n- Use the template below as it is. Keep the style block, the header, the Spindle script and the footer unchanged apart from their placeholders. Fill every {{placeholder}}, repeat blocks as needed, and delete blocks you have nothing for. Never add colours, fonts, libraries, images, or external scripts and styles.\n- Never show a number that is not in sizing.md or ledger.csv. Copy it as printed there.\n- Grade pills show the source letter only (A to D). Tables show the combined grade, e.g. \"B2\", and the ledger id, e.g. \"L7\".\n- Headings and chart titles state the takeaway as a sentence (\"Every rival prices under $40 a month\"), not a topic (\"Pricing\").\n- Citations are real, clickable links. Every number and claim carries one: <a class=\"cite\" href=\"FULL_URL\">Publisher, Mon YYYY</a> <span class=\"grade g-A\">A</span>. The href is the exact page URL you fetched or found in search, copied character for character and starting with https://. Never link a search results page, and never link a homepage when the claim came from a specific page. No URL for a claim means you write \"unverified\" instead of a link.\n- The template's <base target=\"_blank\"> makes every link open in a new tab. Links that jump within the page get target=\"_self\".\n- Visuals are yours to choose. For each point, ask what picture would make a non-expert get it fastest, then draw that, as inline SVG or HTML and CSS. The patterns below are a starter kit, not a menu. Good choices beyond them: a step-by-step journey or flow (how a customer uses it), before and after, a 100-dot grid (\"7 in 100 cafes\"), a scale comparison against something familiar, a value chain showing who pays whom, a map of Australia by state, a simple annotated sketch of the product, a ranked list with bars, a quote card from a real customer review.\n- Whatever you draw: use a viewBox with width=\"100%\" so it scales, label values on the visual itself, use only the palette colours (grey #9AA3B5 for context, Telstra blue #0D54FF for what matters), and put a source line under anything that shows a number. Never distort a number to make a picture work.\n- No text may overlap another label, dot or line. Before writing an SVG, list each label's x, y and rough width (7 units per character at 12px) and move any that collide. Keep every mark at least 15 units inside the viewBox edge.\n- One visual per finding. A finding with no number worth drawing gets a big stat, a quote or a small diagram, not a decorative chart. Vary the visuals: three bar charts in a row is a dull report.\n- Long tables and detail go inside <details> so the page stays short.\n- Load Plain Writing before you write the prose.\n\nColours (already defined in the template): ink #0A0F24, Telstra blue #0D54FF, deep blue #0A2FA8, soft blue #E8EEFF, green #0A8A4A good, gold #B7791F caution, red #D0021B bad, grey #9AA3B5 context, amber #F44E1A for the Spindle mark only. Scores 4 to 5 use green, 3 uses gold, 1 to 2 use red.\n\nResearch report sections (Market Research)\n1. Hero: idea name, verdict pill (Pursue, Pilot to test, Rethink, Park), two sentences on why.\n2. Tiles: \"Do people want it?\", \"Will it make money?\", \"Can we build it?\" as score/5. Each sub-line gives confidence and evidence level in plain words: evidence level 0 \"no evidence yet\", 1 to 3 \"desk research only\", 4 \"customer commitments\", 5 \"repeat paying customers\". Example: \"Medium confidence \u00b7 desk research only\". Then \"Right fit for Telstra?\" with Pass, Fail or Unclear (good, bad or mid) and the reason in a few words as its sub-line. Then \"Market we could serve\" with the SAM base and range.\n3. DVF bars (pattern A), titled in plain words, with the lens names under each bar.\n4. Market size: nested circles (pattern B) beside the bottom-up formula chips, plus one line on whether top-down and bottom-up agree. Then the biggest swing line, the three reality-check chips, and the Expansion TAM line if research.md has one (all under pattern B). Inputs table (Ledger | Input | Low | Base | High | Grade | Source) and method notes in <details>.\n5. Key findings: 3 to 5 cards, each with a takeaway title, one visual and a citation.\n6. Competitors: positioning map (pattern D) on the two axes that matter most in this market, with the competitor table in <details>.\n7. Riskiest assumptions: assumptions map (pattern C), then the top three with their Test Cards.\n8. What we still don't know.\n9. Sources: every source, linked and graded, best grade first, with the ledger ids it supports.\n\nTemplate\n<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>{{Idea name}} | Research report</title>\n<base target=\"_blank\">\n<style>\n:root{--ink:#0A0F24;--muted:#5A6275;--line:#E3E6EE;--soft:#F5F7FB;--blue:#0D54FF;--deep:#0A2FA8;--blue-soft:#E8EEFF;--green:#0A8A4A;--gold:#B7791F;--red:#D0021B}\n*{box-sizing:border-box}html{-webkit-print-color-adjust:exact;print-color-adjust:exact}\nbody{margin:0;background:#fff;color:var(--ink);font:15px/1.55 Inter,system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif}\na{color:var(--blue)}a:hover{text-decoration:none}\nheader{display:flex;align-items:center;gap:12px;padding:14px 32px;border-bottom:1px solid var(--line)}\n#spindle{width:56px;height:35px;flex:none}.brand b{display:block;letter-spacing:-.01em}.brand small{color:var(--muted);font-size:11px}\nheader .meta{margin-left:auto;font-size:12px;color:var(--muted);text-align:right}\n.hero{background:linear-gradient(135deg,var(--blue),var(--deep));color:#fff;padding:40px 32px 44px}\n.hero .kicker{font-size:11px;letter-spacing:.12em;text-transform:uppercase;opacity:.8}\n.hero h1{margin:6px 0 12px;font-size:32px;line-height:1.15;letter-spacing:-.02em;max-width:820px}\n.hero p{max-width:680px;margin:14px 0 0;opacity:.93}\n.pill{display:inline-block;font-weight:800;font-size:12px;letter-spacing:.06em;text-transform:uppercase;padding:6px 14px;border-radius:999px;background:#fff}\n.pill.pursue{color:var(--green)}.pill.pilot{color:var(--blue)}.pill.rethink{color:var(--gold)}.pill.park{color:var(--red)}\nmain{max-width:1000px;margin:0 auto;padding:0 32px 56px}\n.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-top:-22px}\n.tile{background:#fff;border:1px solid var(--line);border-radius:10px;padding:14px 16px;box-shadow:0 2px 10px rgba(10,15,36,.07)}\n.tile .l{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}\n.tile .v{font-size:28px;font-weight:800;line-height:1.2;margin-top:2px}.tile .s{font-size:12px;color:var(--muted)}\n.good{color:var(--green)}.mid{color:var(--gold)}.bad{color:var(--red)}\nsection{margin-top:44px}\nh2{font-size:21px;letter-spacing:-.01em;line-height:1.25;margin:0 0 4px}.sub{color:var(--muted);font-size:13px;margin:0 0 14px}\n.card{border:1px solid var(--line);border-radius:10px;padding:18px;background:#fff}\n.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}\n.card h3{font-size:16px;margin:0 0 8px;line-height:1.3}\n.stat{font-size:40px;font-weight:800;color:var(--blue);line-height:1.1}\n.src{font-size:12px;color:var(--muted);margin-top:8px}\n.cite{font-size:12px;white-space:nowrap}\n.grade{display:inline-block;font-size:10px;font-weight:800;border-radius:4px;padding:1px 6px;vertical-align:1px}\n.g-A{background:#E3F4EA;color:var(--green)}.g-B{background:var(--blue-soft);color:var(--blue)}.g-C{background:#FBF1DE;color:var(--gold)}.g-D{background:#FCE6E8;color:var(--red)}\n.chips{display:flex;flex-wrap:wrap;align-items:center;gap:8px;font-size:14px}\n.chip{background:var(--soft);border:1px solid var(--line);border-radius:8px;padding:8px 12px}.chip b{display:block;font-size:18px}\n.chip.total{background:var(--blue);border-color:var(--blue);color:#fff}\nblockquote{margin:0;padding:12px 16px;border-left:4px solid var(--blue);background:var(--soft);border-radius:0 8px 8px 0}\ntable{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:8px 10px;border-bottom:1px solid var(--line);vertical-align:top}\nth{background:var(--soft);font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted)}\ndetails{margin-top:12px;border:1px solid var(--line);border-radius:10px;padding:10px 16px}\nsummary{cursor:pointer;font-weight:600;color:var(--blue)}\n.unknown li{margin-bottom:6px}\nfooter{margin-top:56px;padding-top:16px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}\n@media(max-width:700px){header,.hero,main{padding-left:16px;padding-right:16px}.hero h1{font-size:26px}header .meta{display:none}}\n</style></head><body>\n<header>\n  <canvas id=\"spindle\" aria-hidden=\"true\"></canvas>\n  <div class=\"brand\"><b>Spindle</b><small>Telstra Muru-D \u00b7 Innovation research</small></div>\n  <div class=\"meta\">Research report<br>{{D Mon YYYY}}</div>\n</header>\n<section class=\"hero\" style=\"margin-top:0\">\n  <div class=\"kicker\">Idea assessment</div>\n  <h1>{{Idea name or one-sentence goal}}</h1>\n  <span class=\"pill {{pursue|pilot|rethink|park}}\">{{Verdict}}</span>\n  <p>{{Two sentences: the answer and the main reason.}}</p>\n</section>\n<main>\n  <div class=\"tiles\">\n    <div class=\"tile\"><div class=\"l\">{{Label}}</div><div class=\"v {{good|mid|bad}}\">{{4/5}}</div><div class=\"s\">{{Medium confidence \u00b7 desk research only}}</div></div>\n    <!-- repeat tile -->\n  </div>\n\n  <section>\n    <h2>{{Takeaway sentence}}</h2>\n    <p class=\"sub\">{{What the visual shows, and the date}}</p>\n    <div class=\"card\">\n      {{SVG from a pattern below}}\n      <div class=\"src\">Source: <a class=\"cite\" href=\"{{https://exact/page}}\">{{Publisher, Mon YYYY}}</a> <span class=\"grade g-{{A}}\">{{A}}</span></div>\n    </div>\n  </section>\n\n  <section>\n    <h2>{{Key findings takeaway}}</h2>\n    <div class=\"grid2\">\n      <div class=\"card\"><h3>{{Finding as a sentence}}</h3><div class=\"stat\">{{$410M}}</div><p>{{One or two sentences.}}</p>\n        <div class=\"src\"><a class=\"cite\" href=\"{{https://exact/page}}\">{{Publisher, Mon YYYY}}</a> <span class=\"grade g-{{B}}\">{{B}}</span></div></div>\n      <!-- repeat card -->\n    </div>\n  </section>\n\n  <section>\n    <h2>{{Detail section takeaway}}</h2>\n    <details><summary>{{Show the full table}}</summary>\n      <table><tr><th>Ledger</th><th>{{Column}}</th><th>Grade</th><th>Source</th></tr>\n        <tr><td>{{L7}}</td><td>{{Value}}</td><td>{{C3}}</td><td><a class=\"cite\" href=\"{{https://exact/page}}\">{{Publisher, Mon YYYY}}</a> <span class=\"grade g-{{C}}\">{{C}}</span></td></tr></table>\n    </details>\n  </section>\n\n  <section>\n    <h2>What we still don't know</h2>\n    <ul class=\"unknown\"><li>{{Open question, and what evidence would settle it}}</li></ul>\n  </section>\n\n  <section id=\"sources\">\n    <h2>Sources</h2>\n    <ol><li><a href=\"{{https://exact/page}}\">{{Title, Publisher, D Mon YYYY}}</a> <span class=\"grade g-{{A}}\">{{A}}</span> {{L1, L4}}</li></ol>\n  </section>\n\n  <footer>Spindle \u00b7 Telstra Muru-D \u00b7 Prepared by the {{agent name}} agent on {{D Mon YYYY}} \u00b7 Full findings: <a href=\"research.md\" target=\"_self\">research.md</a> \u00b7 Sources graded A to D \u00b7 Quotes verified on page: {{X}} of {{Y}}.</footer>\n</main>\n<script>\n(()=>{const cv=document.getElementById(\"spindle\"),ctx=cv.getContext(\"2d\"),T=1.5,S=2,Q=.7;let w,h;\nfunction size(){const r=cv.getBoundingClientRect(),d=devicePixelRatio||1;w=r.width;h=r.height;cv.width=w*d;cv.height=h*d;ctx.setTransform(d,0,0,d,0,0)}\nfunction draw(t){ctx.clearRect(0,0,w,h);const cy=h/2,R=h*.38,ph=t/1000*1.6,n=Math.floor(w/S),pts=[];\nfor(let i=0;i<=n;i++){const u=i/n,r=R*Math.pow(Math.sin(Math.PI*u),.8);for(let k=0;k<2;k++){const th=u*T*Math.PI*2-ph+k*Math.PI;pts.push([i*S,cy+r*Math.cos(th),Math.sin(th)])}}\npts.sort((a,b)=>a[2]-b[2]);ctx.fillStyle=\"#F44E1A\";ctx.globalAlpha=.18;for(let i=0;i<=n;i+=2)ctx.fillRect(i*S-Q,cy-Q,2*Q,2*Q);\nfor(const[x,y,z]of pts){const s=(2+(z+1)*1.25)*Q;ctx.globalAlpha=.25+(z+1)*.375;ctx.fillRect(x-s/2,y-s/2,s,s)}ctx.globalAlpha=1}\nsize();if(matchMedia(\"(prefers-reduced-motion: reduce)\").matches)draw(0);else{const loop=t=>{draw(t);requestAnimationFrame(loop)};requestAnimationFrame(loop)}})();\n</script>\n</body></html>\n\nStarter patterns. Use one when it fits, adapt it freely, or draw something better.\n\nA. DVF bars: one row per lens, 120 units per score point, so a bar's width = score x 120. Fill: green 4 to 5, gold 3, red 1 to 2.\n<svg viewBox=\"0 0 760 190\" width=\"100%\" role=\"img\" aria-label=\"DVF scores\">\n  <g font-size=\"14\" fill=\"#0A0F24\">\n    <text x=\"0\" y=\"24\" font-weight=\"700\">Do people want it? 4/5 <tspan font-weight=\"400\" fill=\"#5A6275\">Desirability</tspan></text><text x=\"730\" y=\"24\" text-anchor=\"end\" fill=\"#5A6275\">Medium confidence</text>\n    <rect x=\"0\" y=\"34\" width=\"730\" height=\"18\" rx=\"9\" fill=\"#EEF1F6\"/><rect x=\"0\" y=\"34\" width=\"480\" height=\"18\" rx=\"9\" fill=\"#0A8A4A\"/>\n    <text x=\"0\" y=\"84\" font-weight=\"700\">Will it make money? 3/5 <tspan font-weight=\"400\" fill=\"#5A6275\">Viability</tspan></text><text x=\"730\" y=\"84\" text-anchor=\"end\" fill=\"#5A6275\">Medium confidence</text>\n    <rect x=\"0\" y=\"94\" width=\"730\" height=\"18\" rx=\"9\" fill=\"#EEF1F6\"/><rect x=\"0\" y=\"94\" width=\"360\" height=\"18\" rx=\"9\" fill=\"#B7791F\"/>\n    <text x=\"0\" y=\"144\" font-weight=\"700\">Can we build it? 4/5 <tspan font-weight=\"400\" fill=\"#5A6275\">Feasibility</tspan></text><text x=\"730\" y=\"144\" text-anchor=\"end\" fill=\"#5A6275\">Medium confidence</text>\n    <rect x=\"0\" y=\"154\" width=\"730\" height=\"18\" rx=\"9\" fill=\"#EEF1F6\"/><rect x=\"0\" y=\"154\" width=\"480\" height=\"18\" rx=\"9\" fill=\"#0A8A4A\"/>\n  </g>\n</svg>\n(The track is 730 wide but scores use 600 for 5/5, which leaves room on the right.)\n\nB. Market size, nested circles. Not to scale: say so in the sub line.\n<svg viewBox=\"0 0 420 300\" width=\"100%\" style=\"max-width:420px\" role=\"img\" aria-label=\"TAM SAM SOM\">\n  <circle cx=\"210\" cy=\"150\" r=\"140\" fill=\"#E8EEFF\"/><circle cx=\"210\" cy=\"192\" r=\"96\" fill=\"#B9CCFF\"/><circle cx=\"210\" cy=\"238\" r=\"50\" fill=\"#0D54FF\"/>\n  <text x=\"210\" y=\"42\" text-anchor=\"middle\" font-size=\"13\" fill=\"#0A2FA8\" font-weight=\"700\">TAM $1.2B</text><text x=\"210\" y=\"60\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5A6275\">$0.9B to $1.5B</text>\n  <text x=\"210\" y=\"122\" text-anchor=\"middle\" font-size=\"13\" fill=\"#0A2FA8\" font-weight=\"700\">SAM $410M</text><text x=\"210\" y=\"140\" text-anchor=\"middle\" font-size=\"11\" fill=\"#0A2FA8\">$300M to $520M</text>\n  <text x=\"210\" y=\"236\" text-anchor=\"middle\" font-size=\"14\" fill=\"#fff\" font-weight=\"800\">SOM $24M</text><text x=\"210\" y=\"254\" text-anchor=\"middle\" font-size=\"11\" fill=\"#fff\">by year 3</text>\n</svg>\nBottom-up formula beside it:\n<div class=\"chips\"><div class=\"chip\"><b>62,000</b>firms</div>\u00d7<div class=\"chip\"><b>1</b>site each</div>\u00d7<div class=\"chip\"><b>$1,080</b>a year</div>=<div class=\"chip total\"><b>$67M</b>TAM base</div></div>\nBiggest swing, one line from the tornado's top two drivers:\n<p class=\"sub\">What moves the answer most: {{firms that need it}} ({{SOM $2M to $9M}}), then {{price}} ({{$4M to $6M}}).</p>\nReality checks on the year-3 estimate, one chip each, Pass in good, Fail in bad:\n<div class=\"chips\"><div class=\"chip\"><b class=\"good\">Pass</b>{{Fits how fast new products usually spread}}</div><div class=\"chip\"><b class=\"bad\">Fail</b>{{Above the nearest peer at the same age}}</div><div class=\"chip\"><b class=\"good\">Pass</b>{{Rivals plus us fit in the market}}</div></div>\nExpansion TAM, only if research.md has one. A separate dashed line, never added into the circles:\n<div class=\"chip\" style=\"border-style:dashed;margin-top:10px\">{{If cheaper access grows usage}}: {{$X to $Y}} more a year (Expansion TAM, not counted above)</div>\n\nC. Assumptions map. Evidence level 0 to 5 left to right: x = 80 + evidence x 80. Importance 1 to 5 bottom to top: y = 330 - (importance - 1) x 70. The red zone (evidence level 2 or less, importance 3 or more) is \"test first\"; its label sits above the zone so no dot can cover it. Each dot is lettered by lens with its number.\n<svg viewBox=\"0 0 520 390\" width=\"100%\" style=\"max-width:560px\" role=\"img\" aria-label=\"Assumptions map\">\n  <text x=\"60\" y=\"26\" font-size=\"12\" fill=\"#D0021B\" font-weight=\"700\">Test first: matters most, least known</text>\n  <rect x=\"60\" y=\"34\" width=\"220\" height=\"171\" fill=\"#FCE6E8\"/>\n  <line x1=\"60\" y1=\"350\" x2=\"500\" y2=\"350\" stroke=\"#C9CEDA\"/><line x1=\"60\" y1=\"34\" x2=\"60\" y2=\"350\" stroke=\"#C9CEDA\"/>\n  <text x=\"280\" y=\"380\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5A6275\">Evidence we have, level 0 to 5 \u2192</text>\n  <text x=\"24\" y=\"190\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5A6275\" transform=\"rotate(-90 24 190)\">Importance \u2192</text>\n  <circle cx=\"80\" cy=\"50\" r=\"13\" fill=\"#0D54FF\"/><text x=\"80\" y=\"55\" text-anchor=\"middle\" font-size=\"11\" fill=\"#fff\" font-weight=\"700\">D1</text>\n  <circle cx=\"160\" cy=\"120\" r=\"13\" fill=\"#0A8A4A\"/><text x=\"160\" y=\"125\" text-anchor=\"middle\" font-size=\"11\" fill=\"#fff\" font-weight=\"700\">V2</text>\n  <circle cx=\"400\" cy=\"190\" r=\"13\" fill=\"#B7791F\"/><text x=\"400\" y=\"195\" text-anchor=\"middle\" font-size=\"11\" fill=\"#fff\" font-weight=\"700\">F3</text>\n</svg>\nTwo assumptions with the same scores share a spot: nudge the second 30 units right so both stay readable.\nLens colours: D blue #0D54FF, V green #0A8A4A, F gold #B7791F. List the numbered assumptions under the map.\n\nD. Positioning map: two axes that matter in this market, rivals in grey with names and prices, the open space or our position in blue. The open-space box must contain no rival; if rivals sit there, the space is not open, so mark our position instead. Labels sit to the right of their dot; when two dots are within 20 units vertically, put one label on the left (text-anchor=\"end\", x = cx - 18).\n<svg viewBox=\"0 0 900 300\" width=\"100%\" role=\"img\" aria-label=\"Competitor map\">\n  <line x1=\"60\" y1=\"260\" x2=\"880\" y2=\"260\" stroke=\"#C9CEDA\"/><line x1=\"60\" y1=\"20\" x2=\"60\" y2=\"260\" stroke=\"#C9CEDA\"/>\n  <text x=\"470\" y=\"290\" font-size=\"12\" fill=\"#5A6275\" text-anchor=\"middle\">{{x axis}} \u2192</text>\n  <text x=\"24\" y=\"140\" font-size=\"12\" fill=\"#5A6275\" text-anchor=\"middle\" transform=\"rotate(-90 24 140)\">{{y axis}} \u2192</text>\n  <circle cx=\"150\" cy=\"210\" r=\"11\" fill=\"#9AA3B5\"/><text x=\"168\" y=\"214\" font-size=\"12\" fill=\"#0A0F24\">Rival A $29</text>\n  <rect x=\"580\" y=\"40\" width=\"260\" height=\"120\" rx=\"12\" fill=\"#E8EEFF\" stroke=\"#0D54FF\" stroke-dasharray=\"6 5\"/>\n  <text x=\"710\" y=\"95\" font-size=\"15\" font-weight=\"700\" fill=\"#0D54FF\" text-anchor=\"middle\">Open: managed tier</text>\n</svg>\n\nOther numbers: a bar chart for comparing categories (horizontal bars, sorted, largest first, grey with the important one in blue), a line for trends over time. Load Data Visualisation if unsure which form to use.\n\nPublish\n1. write_file report.html in your own directory, next to your markdown.\n2. read_file it back and check: no {{ left; every a.cite href starts with https:// and is a real page you used; every number appears in sizing.md or ledger.csv; every section heading is a sentence; no colours outside the palette.\n3. next_free_port, then run_command in the background: python3 -m http.server <port> --bind 0.0.0.0 --directory <your own directory>.\n4. publish_preview with title \"Research report\", that port, and path \"/report.html\".\n5. In your reply, give the preview link and the verdict.",
  "description": "Load after research.md is written, to turn it into the research report.html and publish it beside the chat."
}$p$::jsonb,
   true,
   82);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$evidence_ledger$p$,
   $p$Evidence Ledger$p$,
   $p$The per-number ledger, the sizing script and the quote check for market research.$p$,
   $p${
  "text": "Every number gets a receipt. You record it, code computes from it, and a script checks it is really on the page.\n\n1. The ledger\nEvery number you will use goes into ledger.csv in your own directory (write_file). One row per figure. Columns, exactly in this order:\nid,value,unit,currency,metric,geography,data_year,scope,quote,url,publisher,published,source_grade,claim_grade,downgrades,group,archive_url,verified\n- id: L1, L2, L3 ...\n- value: a plain number. 996203, not \"996,203\", \"~1M\" or \"$1M\".\n- unit: firms, seats, AUD per month, %, and so on.\n- currency: AUD, USD, or blank for counts.\n- metric: count, price, revenue, spend, GMV, rate.\n- data_year: the year the figure measures, e.g. FY2025-26 or 2024. Not the publish date.\n- scope: the segment it covers, e.g. \"employing businesses, ANZSIC M\".\n- quote: the exact sentence from the fetched page that contains the number, copied character for character.\n- url: the exact page you fetched. published: its publish date, YYYY-MM-DD.\n- source_grade A-D, claim_grade 1-6, downgrades: from Source Grading.\n- group: the independence group. Copies and co-owned publishers share one group name.\n- archive_url and verified: leave empty when you add the row.\nValid CSV: wrap any field that contains a comma or a double quote in double quotes, and double any double quote inside it.\nNo quote, no row. No row, the number doesn't go in the report.\nAssumptions are not ledger rows. They live in sizing.py with ledger None.\n\n2. Files you can't web_fetch\nXLSX, PDF and CSV sources: download them in the sandbox with run_command (curl -L -o file URL) and read them with python. pip install openpyxl or pypdf if needed. web_fetch can't read them and truncates at 20,000 characters. For a row from a spreadsheet, quote the cell's row label and value as they appear.\n\n3. Computation\nCopy sizing.py below into your own directory. Fill INPUTS with ledger ids and assumptions, and fill model(). Run: python3 sizing.py > sizing.md\nEvery TAM, SAM, SOM, range, conversion and percentage in research.md and report.html comes from sizing.md. Never type a computed number. To change a number, change the ledger or sizing.py and run it again.\n\n4. Verification\nAfter research and before you write research.md: copy verify.py below into your own directory and run python3 verify.py. It writes verify.csv.\n- found and found_loose: done. found_loose means it matched once punctuation and spacing were ignored.\n- no_quote: add the quote, or drop the row.\n- not_found: re-read the page with web_fetch. Fix the quote, or drop the row and everything built on it.\n- fetch_failed: check the page with web_fetch yourself. Set verified to \"checked_manual\" only if you see the sentence.\nRe-run until clean, then re-run sizing.py if any row changed.\nState the result in research.md, e.g. \"Quotes verified on page: 31 of 33; 2 checked by hand\".\n\n5. Citing\nCite ledger ids in research.md tables, e.g. \"L7\".\n\nverify.py\n\"\"\"Check each ledger quote appears on its source page. Usage: python3 verify.py [ledger.csv]\"\"\"\nimport csv, html, io, json, re, sys, zipfile\nimport urllib.error, urllib.parse, urllib.request\nimport xml.etree.ElementTree as ET\nfrom concurrent.futures import ThreadPoolExecutor\n\nUA = \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124.0 Safari/537.36\"\nWAYBACK = \"https://archive.org/wayback/available?url=\"\nCAP = 10 * 1024 * 1024\n\n\ndef get(url):\n    with urllib.request.urlopen(urllib.request.Request(url, headers={\"User-Agent\": UA}), timeout=20) as r:\n        return r.read(CAP), r.headers.get(\"Content-Type\", \"\").lower()\n\n\ndef xlsx_text(data):\n    out, z = [], zipfile.ZipFile(io.BytesIO(data))\n    for n in z.namelist():\n        if n == \"xl/sharedStrings.xml\" or n.startswith(\"xl/worksheets/sheet\"):\n            for el in ET.fromstring(z.read(n)).iter():\n                tag = el.tag.rsplit(\"}\", 1)[-1]\n                if tag in (\"t\", \"v\") and el.text:\n                    out.append(el.text)\n                if tag == \"c\" and el.get(\"t\") == \"s\":  # shared-string cell: v is an index, skip\n                    for v in el:\n                        v.text = None\n    return \" \".join(out)\n\n\ndef extract(url, data, ctype):\n    \"\"\"Return (text, None) or (None, (status, detail)).\"\"\"\n    path = urllib.parse.urlparse(url).path.lower()\n    if \"pdf\" in ctype or path.endswith(\".pdf\"):\n        try:\n            import pypdf\n        except ImportError:\n            return None, (\"binary_unchecked\", \"pip install pypdf\")\n        return \" \".join(p.extract_text() or \"\" for p in pypdf.PdfReader(io.BytesIO(data)).pages), None\n    if \"spreadsheetml\" in ctype or path.endswith(\".xlsx\"):\n        return xlsx_text(data), None\n    text = data.decode(\"utf-8\", \"replace\")\n    if \"html\" in ctype or path.endswith((\".htm\", \".html\")):\n        text = re.sub(r\"(?is)<(script|style|noscript)\\b.*?</\\1\\s*>\", \" \", text)\n        text = html.unescape(re.sub(r\"<[^>]+>\", \" \", text))\n    return text, None\n\n\ndef norm(s):\n    s = s.casefold().translate({0xA0: \" \", 0x2009: \" \", 0x202F: \" \", 0x2018: \"'\", 0x2019: \"'\",\n                                0x201C: '\"', 0x201D: '\"', 0x2013: \"-\", 0x2014: \"-\"})\n    return re.sub(r\"\\s+\", \" \", s).strip()\n\n\ndef load(url):\n    \"\"\"-> (normalised text, None) or (None, (status, detail)).\"\"\"\n    try:\n        text, err = extract(url, *get(url))\n    except urllib.error.HTTPError as e:\n        return None, (\"fetch_failed\", str(e.code))\n    except Exception as e:\n        return None, (\"fetch_failed\", type(e).__name__)\n    return (norm(text), None) if err is None else (None, err)\n\n\ndef wayback(url):\n    try:\n        return json.loads(get(WAYBACK + urllib.parse.quote(url, safe=\"\"))[0])[\"archived_snapshots\"][\"closest\"][\"url\"]\n    except Exception:\n        return \"none\"\n\n\ndef check(quote, page):\n    q = norm(quote)\n    if not q:\n        return \"no_quote\", \"\"\n    detail = \"\" if re.search(r\"\\d\", q) else \"quote has no digits\"\n    if q in page:\n        return \"found\", detail\n    alnum = lambda s: re.sub(r\"[\\W_]+\", \"\", s)\n    return (\"found_loose\" if alnum(q) in alnum(page) else \"not_found\"), detail\n\n\ndef main(path=\"ledger.csv\"):\n    with open(path, newline=\"\", encoding=\"utf-8\") as f:\n        rd = csv.DictReader(f)\n        cols, rows = rd.fieldnames, list(rd)\n    urls = sorted({r[\"url\"] for r in rows if r[\"url\"]})\n    with ThreadPoolExecutor(8) as ex:\n        pages = dict(zip(urls, ex.map(load, urls)))\n        snaps = dict(zip(urls, ex.map(wayback, urls)))\n    report = []\n    for r in rows:\n        page, err = pages.get(r[\"url\"], (None, (\"fetch_failed\", \"no url\")))\n        status, detail = check(r[\"quote\"], page) if err is None else err\n        r[\"verified\"] = status\n        r[\"archive_url\"] = r[\"archive_url\"] or snaps.get(r[\"url\"], \"none\")\n        report.append({\"id\": r[\"id\"], \"url\": r[\"url\"], \"status\": status, \"detail\": detail})\n    for fn, fields, data in ((path, cols, rows), (\"verify.csv\", [\"id\", \"url\", \"status\", \"detail\"], report)):\n        with open(fn, \"w\", newline=\"\", encoding=\"utf-8\") as f:\n            w = csv.DictWriter(f, fields)\n            w.writeheader()\n            w.writerows(data)\n    bad = [x for x in report if not x[\"status\"].startswith(\"found\")]\n    n = lambda s: sum(x[\"status\"] == s for x in report)\n    print(f\"verified {len(report) - len(bad)} of {len(report)} quotes ({n('not_found')} not_found, {n('fetch_failed')} fetch_failed)\")\n    for x in bad + [x for x in report if x[\"detail\"] == \"quote has no digits\"]:\n        print(f\"  {x['id']}: {x['status']} {x['detail']}\".rstrip())\n\n\nif __name__ == \"__main__\":\n    main(*sys.argv[1:2])\n\nsizing.py\n\"\"\"Market sizing skeleton. Edit INPUTS and model(), then: python3 sizing.py > sizing.md\"\"\"\nimport csv, itertools, math\n\n# max caps a widened rate (shares, conversion, churn) at 1.\n# ponytail: assumption ranges get a fixed widening (0.5x..1.5x), calibrate against an eval set later\nINPUTS = {\n    \"firms\":     dict(ledger=\"L1\", low=None, base=None, high=None, note=\"target firms\"),\n    \"seats\":     dict(ledger=None, low=20, base=50, high=80, note=\"seats per firm\"),\n    \"price\":     dict(ledger=\"L2\", low=None, base=None, high=None, note=\"AUD per seat per year, realised\"),\n    \"sam_share\": dict(ledger=None, low=0.2, base=0.3, high=0.4, max=1, note=\"share matching our segment\"),\n    \"reach\":     dict(ledger=None, low=0.01, base=0.02, high=0.03, max=1, note=\"share of SAM firms reached per year\"),\n    \"conv\":      dict(ledger=None, low=0.1, base=0.2, high=0.3, max=1, note=\"reached to customer\"),\n    \"acv\":       dict(ledger=None, low=20000, base=30000, high=40000, note=\"AUD annual contract value\"),\n    \"churn\":     dict(ledger=None, low=0.05, base=0.1, high=0.15, max=1, note=\"annual churn\"),\n}\nCOMPETITOR_REVENUE = []  # optional: annual revenue of named competitors inside the SAM\n\n\ndef model(x):\n    tam = x[\"firms\"] * x[\"seats\"] * x[\"price\"]\n    sam = tam * x[\"sam_share\"]\n    new = x[\"firms\"] * x[\"sam_share\"] * x[\"reach\"] * x[\"conv\"]  # new customers per year\n    cust = 0\n    for _ in range(3):\n        cust = cust * (1 - x[\"churn\"]) + new\n    return {\"TAM\": tam, \"SAM\": sam, \"SOM\": cust * x[\"acv\"]}\n\n\ndef bass_cumulative(t, p=0.03, q=0.38):\n    e = math.exp(-(p + q) * t)\n    return (1 - e) / (1 + (q / p) * e)\n\n\ndef annualise(monthly):\n    return monthly * 12\n\n\ndef fmt(n, usd=False):\n    suf = \"\"\n    for div, s in ((1e9, \"B\"), (1e6, \"M\"), (1e3, \"K\")):\n        if abs(n) >= div:\n            n, suf = n / div, s\n            break\n    return f\"{'$' if usd else ''}{float(f'{n:.2g}'):g}{suf}\"\n\n\ndef prepare():\n    with open(\"ledger.csv\", newline=\"\", encoding=\"utf-8\") as f:\n        vals = {r[\"id\"]: float(r[\"value\"]) for r in csv.DictReader(f)}\n    for v in INPUTS.values():\n        if v[\"ledger\"]:\n            v[\"base\"] = vals[v[\"ledger\"]] if v[\"base\"] is None else v[\"base\"]\n            v[\"low\"] = v[\"base\"] if v[\"low\"] is None else v[\"low\"]\n            v[\"high\"] = v[\"base\"] if v[\"high\"] is None else v[\"high\"]\n            v[\"tag\"] = v[\"ledger\"]\n        else:\n            lo, hi = v[\"base\"] * 0.5, v[\"base\"] * 1.5\n            v[\"tag\"] = \"assumption, widened\"\n            v[\"low\"], v[\"high\"] = min(v[\"low\"], lo), min(max(v[\"high\"], hi), v.get(\"max\", math.inf))\n\n\ndef table(head, body):\n    return [\"| \" + \" | \".join(head) + \" |\", \"|\" + \"---|\" * len(head)] + [\"| \" + \" | \".join(r) + \" |\" for r in body]\n\n\ndef main():\n    prepare()\n    names = list(INPUTS)\n    base = {k: INPUTS[k][\"base\"] for k in names}\n    ends = lambda k: (INPUTS[k][\"low\"], INPUTS[k][\"high\"])\n    b = model(base)\n    if len(names) <= 12:\n        runs = [model(dict(zip(names, c))) for c in itertools.product(*map(ends, names))]\n        note = f\"Outer range: all 2^{len(names)} low/high combinations.\"\n    else:\n        runs = [model({**base, k: e}) for k in names for e in ends(k)]\n        note = \"More than 12 inputs: outer range is one-at-a-time extremes only.\"\n    print(\"## Layers\\n\")\n    print(\"\\n\".join(table([\"Layer\", \"Outer low\", \"Base\", \"Outer high\"],\n          [[L, fmt(min(r[L] for r in runs), True), fmt(b[L], True), fmt(max(r[L] for r in runs), True)] for L in b])))\n    print(f\"\\n{note}\\n\\n## Tornado (top 2 inputs per layer)\\n\")\n    sw = {k: [model({**base, k: e}) for e in ends(k)] for k in names}\n    for L in b:\n        top = sorted(names, key=lambda k: abs(sw[k][1][L] - sw[k][0][L]), reverse=True)[:2]\n        print(f\"- {L}: \" + \"; \".join(f\"{k} {fmt(sw[k][0][L], True)} / {fmt(sw[k][1][L], True)}\" for k in top))\n    print(\"\\n## Inputs\\n\")\n    print(\"\\n\".join(table([\"Input\", \"Low\", \"Base\", \"High\", \"Ledger id or assumption\"],\n          [[k, fmt(v[\"low\"]), fmt(v[\"base\"]), fmt(v[\"high\"]), v[\"tag\"]] for k, v in INPUTS.items()])))\n    print(\"\\n## Cross-checks\\n\")\n    ceil = bass_cumulative(3) * b[\"SAM\"]\n    print(f\"- Bass year-3 ceiling {fmt(ceil, True)} vs SOM {fmt(b['SOM'], True)}: \" + (\"FLAG SOM exceeds ceiling\" if b[\"SOM\"] > ceil else \"ok\"))\n    if COMPETITOR_REVENUE:\n        tot = sum(COMPETITOR_REVENUE) + b[\"SOM\"]\n        print(f\"- Competitors + SOM {fmt(tot, True)} vs SAM {fmt(b['SAM'], True)}: \" + (\"FLAG over SAM\" if tot > b[\"SAM\"] else \"ok\"))\n\n\nif __name__ == \"__main__\":\n    main()",
  "description": "Load before recording any number: the ledger, the sizing script, and the quote check."
}$p$::jsonb,
   true,
   83);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$scope_report$p$,
   $p$Scope Report$p$,
   $p$The scope report template and how to publish it.$p$,
   $p${
  "text": "Turn your finished scope.md into report.html: a professional Telstra-style scope report in light mode, for a Telstra innovation lab team deciding what to build, how long it takes, what it costs, what it needs and what could stop it. The markdown comes first. The report is a tuned view of it: no new claims.\n\nHow it reads: the first screen answers the whole question in one sentence. Each band down the page goes one level deeper. The working and sources come last.\n\nWrite for two readers on one page. The top must make sense to someone with no technical or project background; the bottom must satisfy an expert checking your estimates.\n- Top (hero, What we're building): everyday words, short sentences, no jargon or acronyms. Say \"must have\" before \"MoSCoW\", \"how ready the technology is\" before \"TRL\". If a term must appear, its plain meaning goes first and the term follows.\n- Middle (Plan and cost to Risks): plain words with the standard terms named once, each claim with its number and citation.\n- Bottom (inside <details>, the estimate table, sources): full expert detail. Formulas with every input, the day rate and its source, the scoring rubric, confidence reasoning. Precise terms are fine here.\n- Band labels and section headings use plain words. Never open a section with an acronym.\n- Test the top: would a new graduate in any team get the answer and the reason without asking you? If not, rewrite it.\n\nRules\n- Use the template below as it is. Keep the style block, the header, the Spindle script and the footer unchanged. Fill every {{placeholder}}, repeat blocks as needed, and delete blocks you have nothing for. Never add colours, fonts, libraries, images, or external scripts and styles.\n- Repeat the element or group just before each <!-- repeat --> once per item.\n- Headings state the takeaway as a sentence (\"Legal sign-off sets the end date\"), not a topic (\"Timeline\").\n- Citations are real, clickable links. Every number and claim carries one: <a class=\"cite\" href=\"FULL_URL\">Publisher, Mon YYYY</a> <span class=\"grade g-A\">A</span>. The href is the exact page URL you fetched or found in search, copied character for character and starting with https://. Never link a search results page, and never link a homepage when the claim came from a specific page. No URL for a claim means you write \"unverified\" instead of a link. Your own estimates need no link: scope.md's working is their source.\n- The template's <base target=\"_blank\"> makes every link open in a new tab. Links that jump within the page get target=\"_self\".\n- No text may overlap another label, dot or line. Before writing an SVG, list each label's x, y and rough width (7 units per character at 12px) and move any that collide. Keep every mark at least 15 units inside the viewBox edge.\n- No tile or card row at the top and no score bars. The hero sentence carries the numbers.\n- Cut small text the reader can infer: no caption, sub-line or source line that only repeats what the heading or visual already shows. Citations stay wherever a number or claim needs one.\n- Every estimate is a range. Every dollar figure states its day rate, and every day rate states its source or says \"assumption\".\n- The same number reads the same everywhere: hero, timeline, cost bar and estimate table all match scope.md.\n- Expected cost = expected (three-point) person-weeks \u00d7 5 \u00d7 day rate + infrastructure and licences. Best cost = the sum of best person-weeks \u00d7 5 \u00d7 day rate + infrastructure; worst cost the same with worst. The hero, cost bar and estimate table total all use these.\n- Load Plain Writing before you write the prose.\n\nColours (already defined in the template): ink #0A0F24, Telstra blue #0D54FF, deep blue #0A2FA8, soft blue #E8EEFF, mid blue #B9CCFF for worst-case tails, track #EEF1F6, green #0A8A4A good, gold #B7791F caution and the blocker, red #D0021B bad, grey #9AA3B5 context, tints #E3F4EA, #FBF1DE, #FCE6E8, amber #F44E1A for the Spindle mark only. Scores 4 to 5 use green, 3 uses gold, 1 to 2 use red.\n\nScope report sections, in order (the scope.md sections each draws on are in brackets)\n- Hero (Goal, Team, Cost, Feasibility, Risk register): the answer as one sentence, with <em> highlights on the time and the cost and <em class=\"warn\"> on the blocker. The blocker is the top risk (risk A: highest likelihood \u00d7 impact). Reword the sentence to fit the facts (when Feasibility is 2/5 or lower, lead with the blocker), but keep the three highlights. One line under it: feasibility score and confidence, person-weeks and day rate, cost range, time range.\n- Band 1, What we're building (User journey, Deliverables, Non-goals): the journey strip (F), then In / Out / Not decided yet as three columns. In = Deliverables, Out = Non-goals, Not decided yet = the \"Not decided yet\" list.\n- Band 2, Plan and cost (Work packages, Team, Milestones, Cost): the timeline (G), then the cost range bar (H) beside person-weeks by role (I).\n- Band 3, What we need (Requirements, Data inventory): the MoSCoW board (J), then the data table (K).\n- Band 4, Can we build it, in detail (Feasibility): TELOS rows (L) beside a TRL meter for each key piece of technology (M).\n- Band 5, Risks (Risk register): the 5 x 5 risk grid (N) beside each risk's owner and plan.\n- Band 6, The working (Work packages, Cost, Success criteria, Stakeholders, Dependencies, Open questions, Feasibility, the assumptions ledger): the estimate table (O), open by default, then the collapsed sections.\n- Sources: every source, linked and graded, best grade first.\n\nTemplate\n<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>{{Idea name}} | Scope report</title>\n<base target=\"_blank\">\n<style>\n:root{--ink:#0A0F24;--muted:#5A6275;--line:#E3E6EE;--soft:#F5F7FB;--blue:#0D54FF;--deep:#0A2FA8;--blue-soft:#E8EEFF;--green:#0A8A4A;--gold:#B7791F;--red:#D0021B}\n*{box-sizing:border-box}html{-webkit-print-color-adjust:exact;print-color-adjust:exact}\nbody{margin:0;background:#fff;color:var(--ink);font:15px/1.55 Inter,system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif}\na{color:var(--blue)}a:hover{text-decoration:none}\nheader{display:flex;align-items:center;gap:12px;padding:14px 32px;border-bottom:1px solid var(--line)}\n#spindle{width:56px;height:35px;flex:none}.brand b{display:block;letter-spacing:-.01em}.brand small{color:var(--muted);font-size:11px}\nheader .meta{margin-left:auto;font-size:12px;color:var(--muted);text-align:right}\n.hero{background:linear-gradient(135deg,var(--blue),var(--deep));color:#fff;padding:40px 32px 44px}\n.hero .kicker{font-size:11px;letter-spacing:.12em;text-transform:uppercase;opacity:.8}\n.hero .big{margin:6px 0 0;font-size:30px;line-height:1.35;font-weight:600;letter-spacing:-.015em;max-width:860px}\n.big em{font-style:normal;background:rgba(255,255,255,.18);border-radius:6px;padding:0 8px;font-weight:800}\n.big em.warn{background:#FBF1DE;color:var(--gold)}\n.hero .foot{margin-top:16px;font-size:13px;opacity:.85}\nmain{max-width:1000px;margin:0 auto;padding:0 32px 56px}\n.good{color:var(--green)}.mid{color:var(--gold)}.bad{color:var(--red)}.blue{color:var(--blue)}\n.level{display:flex;align-items:center;gap:10px;margin:64px 0 10px;font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);font-weight:700}\nmain>.level:first-child{margin-top:40px}\n.level .dots{display:flex;gap:4px}.level .dots i{width:8px;height:8px;border-radius:50%;background:var(--line)}.level .dots i.on{background:var(--blue)}\n.level:after{content:\"\";flex:1;height:1px;background:var(--line)}\nsection{margin-top:28px}.level+section{margin-top:0}\nh2{font-size:21px;letter-spacing:-.01em;line-height:1.25;margin:0 0 14px}.sub{color:var(--muted);font-size:13px;margin:-10px 0 14px}\n.card{border:1px solid var(--line);border-radius:10px;padding:18px;background:#fff}\n.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}\n.grid3{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}\n.card h3{font-size:16px;margin:0 0 8px;line-height:1.3}\n.cite{font-size:12px;white-space:nowrap}\n.grade{display:inline-block;font-size:10px;font-weight:800;border-radius:4px;padding:1px 6px;vertical-align:1px}\n.g-A{background:#E3F4EA;color:var(--green)}.g-B{background:var(--blue-soft);color:var(--blue)}.g-C{background:#FBF1DE;color:var(--gold)}.g-D{background:#FCE6E8;color:var(--red)}\n.journey{display:flex;flex-wrap:wrap}\n.step{flex:1;min-width:150px;margin:0 22px 10px 0;padding:14px 16px;background:var(--soft);border:1px solid var(--line);border-radius:10px;position:relative}\n.step:last-child{margin-right:0}\n.step:not(:last-child):after{content:\"\u2192\";position:absolute;right:-19px;top:40%;color:var(--blue);font-weight:800}\n.step .n{width:24px;height:24px;border-radius:50%;background:var(--blue);color:#fff;font-size:12px;font-weight:800;display:flex;align-items:center;justify-content:center;margin-bottom:8px}\n.step b{display:block;font-size:14px}.step span{font-size:13px;color:var(--muted)}\n.col h3{display:flex;align-items:center;gap:8px}.col ul{margin:0;padding-left:18px;font-size:14px}.col li{margin-bottom:4px}\n.tag{font-size:11px;font-weight:800;padding:2px 8px;border-radius:4px;letter-spacing:.04em;text-transform:uppercase}\n.t-in{background:#E3F4EA;color:var(--green)}.t-out{background:#FCE6E8;color:var(--red)}.t-tbd{background:#FBF1DE;color:var(--gold)}\n.range{position:relative;height:56px;margin:8px 4px 0}\n.range .track{position:absolute;top:22px;left:0;right:0;height:10px;background:#EEF1F6;border-radius:5px}\n.range .band{position:absolute;top:22px;right:0;height:10px;background:#B9CCFF;border-radius:5px}\n.range .base{position:absolute;top:14px;width:4px;height:26px;margin-left:-2px;background:var(--blue);border-radius:2px}\n.range .lab{position:absolute;top:42px;font-size:12px;color:var(--muted);transform:translateX(-50%);white-space:nowrap}\n.range .lab.b{top:-4px;color:var(--blue);font-weight:800;font-size:13px}\n.range .lab.w{right:0;transform:none}\n.bars div{display:grid;grid-template-columns:170px 1fr 40px;align-items:center;gap:10px;font-size:13px;margin-bottom:6px}\n.bars i{display:block;height:12px;border-radius:6px;background:#9AA3B5}.bars i.hi{background:var(--blue)}\n.moscow{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px}\n.moscow .col{border-radius:10px;padding:12px 14px;border:1px solid var(--line)}\n.moscow .col h3{font-size:13px;text-transform:uppercase;letter-spacing:.06em;margin:0 0 8px}\n.m-must{background:var(--blue-soft)}.m-should{background:var(--soft)}.m-wont{border-style:dashed}\ntable{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:8px 10px;border-bottom:1px solid var(--line);vertical-align:top}\nth{background:var(--soft);font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted)}\n.st{font-size:11px;font-weight:700;padding:2px 8px;border-radius:999px;white-space:nowrap}\n.st-have{background:#E3F4EA;color:var(--green)}.st-ask{background:#FBF1DE;color:var(--gold)}.st-build{background:var(--blue-soft);color:var(--blue)}.st-none{background:#FCE6E8;color:var(--red)}\n.telos .row{display:grid;grid-template-columns:130px 44px 1fr;gap:12px;align-items:start;padding:10px 0;border-bottom:1px solid var(--line);font-size:14px}.telos .row:last-child{border:0}\n.score{font-weight:800}\n.trl{display:flex;gap:3px;margin:6px 0 2px}.trl i{flex:1;height:10px;border-radius:2px;background:#EEF1F6}.trl i.on{background:var(--blue)}\n.trlrow{font-size:13px;margin-bottom:12px}.trlrow b{font-size:14px}\ndetails{margin-top:12px;border:1px solid var(--line);border-radius:10px;padding:10px 16px}\nsummary{cursor:pointer;font-weight:600;color:var(--blue)}\n.formula{font-family:ui-monospace,Consolas,monospace;font-size:13px;background:var(--soft);padding:10px 12px;border-radius:8px;margin:10px 0}\n.risklist{font-size:13px}.risklist div{margin-bottom:10px}\n.rail{position:fixed;right:18px;bottom:24px;display:none;flex-direction:column;gap:12px;font-size:11px}\n.rail a{display:flex;align-items:center;gap:8px;color:var(--muted);text-decoration:none}\n.rail a:before{content:\"\";width:8px;height:8px;border-radius:50%;background:var(--line)}\n.rail a:hover{color:var(--blue)}.rail a:hover:before{background:var(--blue)}\n@media(min-width:1260px){.rail{display:flex}}\nfooter{margin-top:56px;padding-top:16px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}\n@media(max-width:700px){header,.hero,main{padding-left:16px;padding-right:16px}.hero .big{font-size:24px}header .meta{display:none}.bars div{grid-template-columns:120px 1fr 32px}.step{flex-basis:100%;margin-right:0}.step:not(:last-child):after{content:none}.telos .row{grid-template-columns:1fr auto}.telos .row span:last-child{grid-column:1/-1}}\n</style></head><body>\n<header>\n  <canvas id=\"spindle\" aria-hidden=\"true\"></canvas>\n  <div class=\"brand\"><b>Spindle</b><small>Telstra Muru-D \u00b7 Innovation research</small></div>\n  <div class=\"meta\">Scope report<br>{{D Mon YYYY}}</div>\n</header>\n<nav class=\"rail\"><a href=\"#l1\" target=\"_self\">The answer</a><a href=\"#l2\" target=\"_self\">What we're building</a><a href=\"#l3\" target=\"_self\">Plan and cost</a><a href=\"#l4\" target=\"_self\">What we need</a><a href=\"#l5\" target=\"_self\">Can we build it</a><a href=\"#l6\" target=\"_self\">Risks</a><a href=\"#l7\" target=\"_self\">The working</a></nav>\n<section class=\"hero\" style=\"margin-top:0\" id=\"l1\">\n  <div class=\"kicker\">Project scope \u00b7 {{Idea name}}</div>\n  <h1 class=\"big\">We can build this in <em>about {{likely weeks to pilot}} weeks</em> with a team of {{team size, in words}}, for <em>roughly {{expected cost, e.g. $160k}}</em>. The one thing that could stop it is <em class=\"warn\">{{the blocker, in plain words}}</em>{{optional: \", so\" and the first step against it}}.</h1>\n  <div class=\"foot\">Feasibility {{score}}/5, {{high|medium|low}} confidence \u00b7 {{expected}} person-weeks at {{$950}}/day, {{rate source name, or \"assumption\"}} \u00b7 {{best cost}} to {{worst cost}} \u00b7 {{best}} to {{worst}} weeks</div>\n</section>\n<main>\n  <div class=\"level\" id=\"l2\"><span class=\"dots\"><i class=\"on\"></i><i></i><i></i><i></i><i></i><i></i></span>What we're building</div>\n  <section>\n    <h2>{{Takeaway: what the first version does for the user}}</h2>\n    <div class=\"journey\">\n      <div class=\"step\"><div class=\"n\">{{1}}</div><b>{{Step, at most 5 words}}</b><span>{{One line, optional}}</span></div><!-- repeat -->\n    </div>\n  </section>\n  <section>\n    <h2>{{Takeaway: what is in, and what waits}}</h2>\n    <div class=\"grid3\">\n      <div class=\"card col\"><h3><span class=\"tag t-in\">In</span></h3><ul><li>{{Deliverable}}</li><!-- repeat --></ul></div>\n      <div class=\"card col\"><h3><span class=\"tag t-out\">Out</span></h3><ul><li>{{Non-goal}}</li><!-- repeat --></ul></div>\n      <div class=\"card col\"><h3><span class=\"tag t-tbd\">Not decided yet</span></h3><ul><li>{{Undecided item}}</li><!-- repeat --></ul></div>\n    </div>\n  </section>\n\n  <div class=\"level\" id=\"l3\"><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i></i><i></i><i></i><i></i></span>Plan and cost</div>\n  <section>\n    <h2>{{Takeaway: when the pilot lands; name the blocking step if it is not the hero's blocker}}</h2>\n    <div class=\"card\">{{Timeline SVG, pattern G below}}</div>\n  </section>\n  <section>\n    <h2>{{Takeaway: the expected cost and its range}}</h2>\n    <p class=\"sub\">{{expected}} person-weeks at {{$950}}/day, {{rate source as a cite link, or \"assumption\"}}, plus {{$8k}} of {{infrastructure and licences, in plain words}}.</p>\n    <div class=\"grid2\">\n      <div class=\"card\">\n        <div class=\"range\"><div class=\"track\"></div><div class=\"band\" style=\"left:{{best%}}\"></div><div class=\"base\" style=\"left:{{expected%}}\"></div>\n          <div class=\"lab b\" style=\"left:{{expected%}}\">{{$160k}} expected</div><div class=\"lab\" style=\"left:{{best%}}\">{{$100k}} best</div><div class=\"lab w\">{{$250k}} worst</div></div>\n      </div>\n      <div class=\"card\"><h3>Person-weeks by role</h3>\n        <div class=\"bars\"><div><span>{{Role}}</span><i style=\"width:{{width}}%\"></i><span>{{9}}</span></div><!-- repeat --></div>\n      </div>\n    </div>\n  </section>\n\n  <div class=\"level\" id=\"l4\"><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i></i><i></i><i></i></span>What we need</div>\n  <section>\n    <h2>{{Takeaway: how many must-haves, and whether the pilot survives without the rest}}</h2>\n    <div class=\"moscow\">\n      <div class=\"col m-must\"><h3 class=\"blue\">Must have</h3><ul><li>{{Requirement}}</li><!-- repeat --></ul></div>\n      <div class=\"col m-should\"><h3>Should have</h3><ul><li>{{Requirement}}</li><!-- repeat --></ul></div>\n      <div class=\"col\"><h3>Could have</h3><ul><li>{{Requirement}}</li><!-- repeat --></ul></div>\n      <div class=\"col m-wont\"><h3 class=\"bad\">Won't have (now)</h3><ul><li>{{Requirement}}</li><!-- repeat --></ul></div>\n    </div>\n  </section>\n  <section>\n    <h2>{{Takeaway: which data we have, and which to chase}}</h2>\n    <div class=\"card\" style=\"padding:0;overflow:auto\">\n      <table><tr><th>Data</th><th>Used for</th><th>Comes from</th><th>Sensitivity</th><th>Status</th></tr>\n        <tr><td>{{Dataset}}</td><td>{{What it is used for}}</td><td>{{Where it comes from}}</td><td>{{Sensitivity}}</td><td><span class=\"st st-{{have|ask|build|none}}\">{{Have|Need access|We build it|Doesn't exist}}</span></td></tr><!-- repeat -->\n      </table>\n    </div>\n  </section>\n\n  <div class=\"level\" id=\"l5\"><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i></i><i></i></span>Can we build it, in detail</div>\n  <section>\n    <h2>{{Takeaway: what is ready, and which check is weakest}}</h2>\n    <div class=\"grid2\">\n      <div class=\"card telos\">\n        <div class=\"row\"><b>{{Technology|Cost to build and run|Law and privacy|Operations|Schedule}}</b><span class=\"score {{good|mid|bad}}\">{{4}}/5</span><span>{{One line, with its citation}}</span></div><!-- repeat -->\n      </div>\n      <div class=\"card\"><h3>How ready each piece of technology is, 1 (idea) to 9 (proven in market)</h3>\n        <div class=\"trlrow\"><b>{{Piece of technology}}</b> \u00b7 TRL {{6}}<div class=\"trl\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i></i><i></i><i></i></div></div><!-- repeat -->\n      </div>\n    </div>\n  </section>\n\n  <div class=\"level\" id=\"l6\"><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i></i></span>Risks</div>\n  <section>\n    <h2>{{Takeaway: how many risks are red, and the one to act on first}}</h2>\n    <div class=\"grid2\">\n      <div class=\"card\">{{Risk grid SVG, pattern N below}}</div>\n      <div class=\"card risklist\"><div><b>{{A}} {{Risk}}.</b> Owner: {{role}}. Plan: {{mitigation}}.</div><!-- repeat --></div>\n    </div>\n  </section>\n\n  <div class=\"level\" id=\"l7\"><span class=\"dots\"><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i><i class=\"on\"></i></span>The working</div>\n  <section>\n    <h2>How the estimate was built</h2>\n    <details open><summary>Effort by work package (three-point estimate)</summary>\n      <div class=\"formula\">expected = (best + 4 \u00d7 likely + worst) \u00f7 6 \u00b7 cost = person-weeks \u00d7 5 days \u00d7 {{$950}}/day</div>\n      <div style=\"overflow:auto\"><table><tr><th>Work package</th><th>Best</th><th>Likely</th><th>Worst</th><th>Expected (pw)</th><th>Cost</th></tr>\n        <tr><td>{{Work package}}</td><td>{{3}}</td><td>{{4}}</td><td>{{6}}</td><td>{{4.2}}</td><td>{{$20k}}</td></tr><!-- repeat -->\n        <tr><td>{{Infrastructure and licences}}</td><td colspan=\"4\">{{What it covers}}</td><td>{{$8k}}</td></tr>\n        <tr><th>Total</th><th>{{sum}}</th><th>{{sum}}</th><th>{{sum}}</th><th>{{sum}}</th><th>{{expected cost}}</th></tr>\n      </table></div>\n    </details>\n    <details><summary>Success criteria</summary><ul><li>{{Criterion: the number, and how we check it}}</li><!-- repeat --></ul></details>\n    <details><summary>Stakeholders and who signs off</summary><ul><li>{{Who, and their part}}</li><!-- repeat --></ul></details>\n    <details><summary>Assumptions ledger</summary>{{The assumptions ledger table from scope.md}}</details>\n    <details><summary>Dependencies outside this project</summary><ul><li>{{Dependency}}</li><!-- repeat --></ul></details>\n    <details><summary>Open questions</summary><ul><li>{{Question}}</li><!-- repeat --></ul></details>\n    <details><summary>Feasibility scoring and confidence</summary><p>{{Each TELOS check's score and reason, the rubric, why the weakest check sets Feasibility, and the confidence reasoning.}}</p></details>\n  </section>\n\n  <section id=\"sources\">\n    <h2>Sources</h2>\n    <ol><li><a href=\"{{https://exact/page}}\">{{Title, Publisher, D Mon YYYY}}</a> <span class=\"grade g-{{A}}\">{{A}}</span></li></ol>\n  </section>\n\n  <footer>Spindle \u00b7 Telstra Muru-D \u00b7 Prepared by the Project Scoping agent on {{D Mon YYYY}} \u00b7 Full findings: <a href=\"scope.md\" target=\"_self\">scope.md</a> \u00b7 Estimates are ranges.</footer>\n</main>\n<script>\n(()=>{const cv=document.getElementById(\"spindle\"),ctx=cv.getContext(\"2d\"),T=1.5,S=2,Q=.7;let w,h;\nfunction size(){const r=cv.getBoundingClientRect(),d=devicePixelRatio||1;w=r.width;h=r.height;cv.width=w*d;cv.height=h*d;ctx.setTransform(d,0,0,d,0,0)}\nfunction draw(t){ctx.clearRect(0,0,w,h);const cy=h/2,R=h*.38,ph=t/1000*1.6,n=Math.floor(w/S),pts=[];\nfor(let i=0;i<=n;i++){const u=i/n,r=R*Math.pow(Math.sin(Math.PI*u),.8);for(let k=0;k<2;k++){const th=u*T*Math.PI*2-ph+k*Math.PI;pts.push([i*S,cy+r*Math.cos(th),Math.sin(th)])}}\npts.sort((a,b)=>a[2]-b[2]);ctx.fillStyle=\"#F44E1A\";ctx.globalAlpha=.18;for(let i=0;i<=n;i+=2)ctx.fillRect(i*S-Q,cy-Q,2*Q,2*Q);\nfor(const[x,y,z]of pts){const s=(2+(z+1)*1.25)*Q;ctx.globalAlpha=.25+(z+1)*.375;ctx.fillRect(x-s/2,y-s/2,s,s)}ctx.globalAlpha=1}\nsize();if(matchMedia(\"(prefers-reduced-motion: reduce)\").matches)draw(0);else{const loop=t=>{draw(t);requestAnimationFrame(loop)};requestAnimationFrame(loop)}})();\n</script>\n</body></html>\n\nPatterns. F, H to M and O are in the template; G and N are below. Keep the formulas.\n\nF. Journey strip: 3 to 5 steps from User journey, numbered 1 up.\n\nG. Timeline: one row per work package, in start order. Labels sit in the column x 0 to 170: at most 24 characters. Read each row's likely start and End week (likely, worst) straight from the Work packages table; never derive new ones. Let W = the latest worst end across all rows, rounded up to a multiple of 4; week w sits at x = 180 + w \u00d7 (560 / W). With n rows, row i (from 0) has its bar at y = 40 + 34i and its label at y = 52 + 34i. Each bar starts at the likely start. The solid #0D54FF bar runs to the likely end; the #B9CCFF tail behind it runs to the worst end. The blocking row (Team's blocking step) is #B7791F with a #FBF1DE tail and a bold gold label, and keeps its start-order position. The last likely end equals the hero's weeks to pilot. Gridlines every 4 weeks (every 8 past 60 weeks). Milestones are diamonds at y 20 at x = 180 + (milestone target week) \u00d7 (560 / W), with the label at x + 12; if a label (about 6 units per character) would reach the next diamond or x 745, put it on the left instead (text-anchor=\"end\", x - 12), and if that collides too, shorten it.\n<svg viewBox=\"0 0 760 {{82 + 34n}}\" width=\"100%\" role=\"img\" aria-label=\"Timeline\">\n  <g stroke=\"#EEF1F6\"><line x1=\"{{x}}\" y1=\"34\" x2=\"{{x}}\" y2=\"{{28 + 34n}}\"/><!-- repeat --></g>\n  <text x=\"0\" y=\"{{52 + 34i}}\" font-size=\"12\" fill=\"#0A0F24\">{{Work package}}</text>\n  <rect x=\"{{start x}}\" y=\"{{40 + 34i}}\" width=\"{{(worst end - start) \u00d7 560 / W}}\" height=\"16\" rx=\"8\" fill=\"#B9CCFF\"/><rect x=\"{{start x}}\" y=\"{{40 + 34i}}\" width=\"{{(likely end - start) \u00d7 560 / W}}\" height=\"16\" rx=\"8\" fill=\"#0D54FF\"/><!-- repeat -->\n  <text x=\"0\" y=\"{{52 + 34i}}\" font-size=\"12\" fill=\"#B7791F\" font-weight=\"700\">{{Blocking package}}</text>\n  <rect x=\"{{start x}}\" y=\"{{40 + 34i}}\" width=\"{{(worst end - start) \u00d7 560 / W}}\" height=\"16\" rx=\"8\" fill=\"#FBF1DE\"/><rect x=\"{{start x}}\" y=\"{{40 + 34i}}\" width=\"{{(likely end - start) \u00d7 560 / W}}\" height=\"16\" rx=\"8\" fill=\"#B7791F\"/>\n  <path d=\"M{{x}} 20 l6 6 -6 6 -6 -6z\" fill=\"#0A0F24\"/><text x=\"{{x + 12}}\" y=\"30\" font-size=\"11\" fill=\"#0A0F24\">{{Milestone}}</text><!-- repeat -->\n  <g transform=\"translate(0,{{34n}})\" font-size=\"11\" fill=\"#5A6275\">\n    <text x=\"180\" y=\"44\" text-anchor=\"middle\">wk 0</text><text x=\"{{x}}\" y=\"44\" text-anchor=\"middle\">{{4}}</text><!-- repeat -->\n    <rect x=\"180\" y=\"57\" width=\"20\" height=\"10\" rx=\"5\" fill=\"#0D54FF\"/><text x=\"206\" y=\"66\">likely</text>\n    <rect x=\"262\" y=\"57\" width=\"20\" height=\"10\" rx=\"5\" fill=\"#B9CCFF\"/><text x=\"288\" y=\"66\">worst case</text>\n    <rect x=\"368\" y=\"57\" width=\"20\" height=\"10\" rx=\"5\" fill=\"#B7791F\"/><text x=\"394\" y=\"66\">sets the end date</text>\n  </g>\n</svg>\n\nH. Cost range bar: positions are % of the worst case: best% = best \u00f7 worst \u00d7 100, expected% = expected \u00f7 worst \u00d7 100. The band runs from best to the right end, where the worst label sits.\n\nI. Person-weeks by role: one row per role from Team, largest first. Width = the role's person-weeks \u00f7 the largest \u00d7 100. Only the largest bar keeps class=\"hi\" (blue); the rest are grey. Roles at most 24 characters.\n\nJ. MoSCoW board: from Requirements, items under 8 words each.\n\nK. Data table: from Data inventory. Status classes: Have = st-have, Need access = st-ask, We build it = st-build, Doesn't exist = st-none.\n\nL. TELOS rows: all five checks in Feasibility's order. Score class: good 4 to 5, mid 3, bad 1 to 2. The hero's Feasibility score equals the lowest of the five.\n\nM. TRL meter: one row per key piece of technology from Feasibility. 9 segments; the first TRL of them get class=\"on\".\n\nN. Risk grid: likelihood L and impact I run 1 to 5. Cell (L, I) has its top-left at x = 60 + (L-1) \u00d7 50, y = 20 + (5-I) \u00d7 50, and its dot at the centre (x + 25, y + 25). The cells are already filled: #FCE6E8 when L \u00d7 I is 15 or more, #FBF1DE when 8 to 14, otherwise #EEF1F6. Dots use the same bands: red #D0021B, gold #B7791F, grey #9AA3B5. Letter the dots A, B, C in the risk list's order, highest L \u00d7 I first. When two risks share a cell, dots are 24 units wide, so put the first at x + 13 and the second at x + 37 (both at y + 25). A third goes at x + 25, y + 38, with the first two raised to y + 15.\n<svg viewBox=\"0 0 340 320\" width=\"100%\" style=\"max-width:340px\" role=\"img\" aria-label=\"Risk grid\">\n  <g stroke=\"#fff\" stroke-width=\"2\">\n    <rect x=\"60\" y=\"20\" width=\"50\" height=\"50\" fill=\"#EEF1F6\"/><rect x=\"110\" y=\"20\" width=\"50\" height=\"50\" fill=\"#FBF1DE\"/><rect x=\"160\" y=\"20\" width=\"50\" height=\"50\" fill=\"#FCE6E8\"/><rect x=\"210\" y=\"20\" width=\"50\" height=\"50\" fill=\"#FCE6E8\"/><rect x=\"260\" y=\"20\" width=\"50\" height=\"50\" fill=\"#FCE6E8\"/>\n    <rect x=\"60\" y=\"70\" width=\"50\" height=\"50\" fill=\"#EEF1F6\"/><rect x=\"110\" y=\"70\" width=\"50\" height=\"50\" fill=\"#FBF1DE\"/><rect x=\"160\" y=\"70\" width=\"50\" height=\"50\" fill=\"#FBF1DE\"/><rect x=\"210\" y=\"70\" width=\"50\" height=\"50\" fill=\"#FCE6E8\"/><rect x=\"260\" y=\"70\" width=\"50\" height=\"50\" fill=\"#FCE6E8\"/>\n    <rect x=\"60\" y=\"120\" width=\"50\" height=\"50\" fill=\"#EEF1F6\"/><rect x=\"110\" y=\"120\" width=\"50\" height=\"50\" fill=\"#EEF1F6\"/><rect x=\"160\" y=\"120\" width=\"50\" height=\"50\" fill=\"#FBF1DE\"/><rect x=\"210\" y=\"120\" width=\"50\" height=\"50\" fill=\"#FBF1DE\"/><rect x=\"260\" y=\"120\" width=\"50\" height=\"50\" fill=\"#FCE6E8\"/>\n    <rect x=\"60\" y=\"170\" width=\"50\" height=\"50\" fill=\"#EEF1F6\"/><rect x=\"110\" y=\"170\" width=\"50\" height=\"50\" fill=\"#EEF1F6\"/><rect x=\"160\" y=\"170\" width=\"50\" height=\"50\" fill=\"#EEF1F6\"/><rect x=\"210\" y=\"170\" width=\"50\" height=\"50\" fill=\"#FBF1DE\"/><rect x=\"260\" y=\"170\" width=\"50\" height=\"50\" fill=\"#FBF1DE\"/>\n    <rect x=\"60\" y=\"220\" width=\"50\" height=\"50\" fill=\"#EEF1F6\"/><rect x=\"110\" y=\"220\" width=\"50\" height=\"50\" fill=\"#EEF1F6\"/><rect x=\"160\" y=\"220\" width=\"50\" height=\"50\" fill=\"#EEF1F6\"/><rect x=\"210\" y=\"220\" width=\"50\" height=\"50\" fill=\"#EEF1F6\"/><rect x=\"260\" y=\"220\" width=\"50\" height=\"50\" fill=\"#EEF1F6\"/>\n  </g>\n  <g font-size=\"12\" font-weight=\"700\" fill=\"#fff\" text-anchor=\"middle\">\n    <circle cx=\"{{x + 25}}\" cy=\"{{y + 25}}\" r=\"12\" fill=\"{{#D0021B|#B7791F|#9AA3B5}}\"/><text x=\"{{x + 25}}\" y=\"{{y + 29}}\">{{A}}</text><!-- repeat -->\n  </g>\n  <text x=\"185\" y=\"295\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5A6275\">How likely \u2192</text>\n  <text x=\"30\" y=\"145\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5A6275\" transform=\"rotate(-90 30 145)\">How bad \u2192</text>\n</svg>\n\nO. Estimate table: one row per work package, then infrastructure and licences, then the totals. The totals match the hero and the cost bar.\n\nPublish\n1. write_file report.html in your own directory, next to scope.md.\n2. read_file it back and check: no {{ left; no class=\"tile\"; every a.cite href starts with https:// and is a real page you used; every section heading is a sentence; no colours outside the palette.\n3. next_free_port, then run_command in the background: python3 -m http.server <port> --bind 0.0.0.0 --directory <your own directory>.\n4. publish_preview with title \"Scope report\", that port, and path \"/report.html\".\n5. In your reply, give the preview link, the Feasibility score with its confidence, and the time and cost ranges.",
  "description": "Load after scope.md is written, to turn it into report.html and publish it beside the chat."
}$p$::jsonb,
   true,
   83);
insert into public.tool_presets (tool_type_id, slug, name, description, config, is_active, sort_order) values
  ((select id from public.tool_types where slug = $p$skill$p$),
   $p$telstra_design$p$,
   $p$Telstra Design$p$,
   $p$Telstra-style colours, type and components for prototypes.$p$,
   $p${
  "text": "Every prototype looks like a Telstra product: clean, confident, light, plenty of white space, one strong blue. The people judging it are Telstra innovation teams, and it should look like something Telstra could ship.\n\nWho decides what\n- This skill decides colour, type, components, corners, shadows and icons. Where Design Taste, Impeccable or any other skill disagrees on those, this skill wins.\n- Design Taste and Impeccable still guide layout, hierarchy, spacing rhythm and copy. Emil still guides motion.\n- Prototype Design still decides delivery: one file, states, serving.\n\nBrand rules\n- No Telstra logo, T mark or trademarked wordmark. The product's own name, set in bold text, is the logo.\n- No stock photos of people. Use simple inline SVG illustrations or icons, or nothing.\n- Copy sounds like Telstra: plain, warm, direct, Australian spelling (\"organise\", \"colour\"), prices in A$ with GST stated. Say \"you\", not \"the user\".\n\nTokens. Paste this :root block as is and use only these variables.\n:root{\n  --blue:#0D54FF; --blue-hover:#0A43CC; --on-blue:#FFFFFF; --blue-deep:#0A2FA8; --blue-soft:#E8EEFF;\n  --ink:#0A0F24; --ink-2:#3D4459; --muted:#5A6275; --line:#E3E6EE; --bg:#FFFFFF; --surface:#F5F7FB;\n  --green:#067A3E; --green-soft:#E3F4EA; --gold:#8A5A0A; --gold-soft:#FBF1DE; --red:#D0021B; --red-soft:#FCE6E8;\n  --focus:0 0 0 3px rgba(13,84,255,.35);\n  --r-sm:6px; --r:10px; --r-lg:16px; --r-pill:999px;\n  --shadow:0 2px 10px rgba(10,15,36,.07); --shadow-lg:0 12px 32px rgba(10,15,36,.12);\n  --font:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,\"Helvetica Neue\",Arial,sans-serif;\n}\n@media (prefers-color-scheme: dark){:root{\n  --blue:#5C8DFF; --blue-hover:#7EA5FF; --on-blue:#0A0F24; --blue-deep:#0A2FA8; --blue-soft:#16224A;\n  --ink:#F2F4F8; --ink-2:#C9CEDA; --muted:#98A0B3; --line:#262E45; --bg:#0A0F24; --surface:#131A35;\n  --green:#3CCB7F; --green-soft:#10301F; --gold:#E0A54A; --gold-soft:#33260F; --red:#FF6B6B; --red-soft:#3A1418;\n}}\n\nType: var(--font) everywhere. Sizes 40/32/24/20/16/14/12px. Headings 700 with letter-spacing -0.02em; body 16px, line-height 1.55, colour var(--ink); secondary text var(--muted). Sentence case everywhere, never all caps except 12px labels with letter-spacing .08em.\n\nSpacing: multiples of 4px. Sections 64px apart on desktop, 40px on mobile. Content max width 1120px.\n\nComponents. Build from these; restyle nothing outside the tokens.\n- Top bar: white (var(--bg)), 64px tall, bottom border 1px var(--line). Product name left in bold 18px, nav links var(--ink-2) 15px, primary action button right.\n- Hero: a deep blue band, linear-gradient(135deg,var(--blue),var(--blue-deep)), white text, one headline, one sentence, one primary button in white with blue text. Use it once, at the top of a landing or overview screen only.\n- Primary button: background var(--blue), text var(--on-blue), 600 weight, 12px 20px padding, radius var(--r-pill), hover var(--blue-hover). One per screen region.\n- Secondary button: white background, 1.5px var(--blue) border, blue text, same shape.\n- Text button: blue text, no border, underline on hover.\n- Every focusable element: outline none, box-shadow var(--focus) on :focus-visible.\n- Input: 48px tall, 1px var(--line) border, radius var(--r-sm), label above in 14px 600, help text below in 13px var(--muted). Focus border var(--blue). Error: border var(--red), message below in var(--red) with an icon, never colour alone.\n- Card: var(--bg), 1px var(--line) border, radius var(--r), padding 20px, shadow var(--shadow). Clickable cards lift to var(--shadow-lg) on hover.\n- Tag or status pill: radius var(--r-pill), 12px 600, soft background with the strong colour as text: green for success, gold for pending, red for problems, blue for info.\n- Alert banner: soft background, 4px left border in the strong colour, icon, bold first sentence.\n- Table: 14px, header row var(--surface) with 12px uppercase labels, rows separated by 1px var(--line), numbers right-aligned.\n- Tabs: text tabs with a 3px var(--blue) underline on the active one.\n- Empty state: a simple line illustration or icon in var(--blue), one sentence on what goes here, one primary button.\n- Loading: skeleton blocks in var(--surface) with a soft shimmer; never a lone spinner on a blank page.\n- Icons: inline SVG, 24px, stroke 1.75, stroke-linecap round, currentColor. Same style everywhere.\n- Mobile bottom nav (app screens only): 64px, white, top border, 4 or 5 items, active item blue.\n\nColour discipline: blue is for actions and the one thing that matters on a screen. Large areas stay white or var(--surface). Backgrounds use only var(--bg), var(--surface), the soft colours or the blue hero gradient; never var(--ink) or var(--ink-2), which flip to light in dark mode. That includes prototype controls and other demo chrome. Green, gold and red only mean success, caution and problems. Text contrast at least 4.5:1 in both modes.\n\nBefore you publish, check: the :root block is unchanged; no background uses var(--ink); no hex colours outside it; no Telstra logo; every button is one of the three types; focus is visible on every control; the screen works at 400px wide.",
  "description": "Load before building any screen, page or prototype. It sets the colours, type and components."
}$p$::jsonb,
   true,
   83);
